INSERT INTO "public"."decks" (id, name, description, is_active, created_by)
INSERT INTO "public"."decks" (id, name, description, card_back_image_url, bg_image_url, category_images, card_layout) VALUES
('00000000-0000-0000-0000-000000000001', 'default', 'Default story deck with protagonists, antagonists, settings, objects, catalysts, traits, and endings', 'https://utfs.io/f/mock-0228368736dd', NULL, NULL, '{"card_positions":{"protagonist":{"x":100,"y":150,"rotation":0,"scale":1.0},"antagonist":{"x":300,"y":150,"rotation":0,"scale":1.0},"setting":{"x":200,"y":50,"rotation":0,"scale":0.8}},"board_settings":{"background_opacity":0.8,"border_width":5,"card_spacing":20},"ui_elements":{"title_position":{"x":200,"y":20},"score_position":{"x":400,"y":20}}}')
INSERT INTO "public"."cards" (id, deck_id, name, description, type, category, usage_examples, translations, image_url) VALUES
('61bb6ee4-8e14-517b-8d0c-79c992318196', '00000000-0000-0000-0000-000000000001', 'The Reluctant Hero', 'A character who is called to adventure but initially resists their destiny, only to rise when needed most.', 'story', 'protagonist', 'Use when introducing a main character who doubts themselves or when showing character growth.', '{"en":{"name":"The Reluctant Hero","description":"A character who is called to adventure but initially resists their destiny, only to rise when needed most.","usage_examples":"Use when introducing a main character who doubts themselves or when showing character growth."},"ru":{"name":"Неохотный герой","description":"Персонаж, призванный к приключениям, но поначалу сопротивляющийся своей судьбе, чтобы восстать, когда это нужнее всего.","usage_examples":"Используйте, когда представляете главного героя, который сомневается в себе, или когда показываете рост персонажа."},"ua":{"name":"Герой мимоволі","description":"Персонаж, покликаний до пригод, але спочатку опирається своїй долі, щоб повстати, коли це найбільше потрібно.","usage_examples":"Використовуйте, коли представляєте головного героя, який сумнівається в собі, або коли показуєте ріст персонажа."}}', NULL),
('8683b497-2050-5e68-8b8a-b7730a6a7178', '00000000-0000-0000-0000-000000000001', 'The Chosen One', 'A person marked by prophecy or fate to accomplish a great deed, bearing the weight of destiny.', 'story', 'protagonist', 'Play when revealing a character''s special purpose or when prophecy becomes relevant.', '{"en":{"name":"The Chosen One","description":"A person marked by prophecy or fate to accomplish a great deed, bearing the weight of destiny.","usage_examples":"Play when revealing a character''s special purpose or when prophecy becomes relevant."},"ru":{"name":"Избранный","description":"Человек, отмеченный пророчеством или судьбой для совершения великого дела, несущий бремя судьбы.","usage_examples":"Играйте, когда раскрываете особое предназначение персонажа или когда пророчество становится актуальным."},"ua":{"name":"Обраний","description":"Людина, позначена пророцтвом або долею для здійснення великого вчинку, що несе тягар долі.","usage_examples":"Грайте, коли розкриваєте особливе призначення персонажа або коли пророцтво стає актуальним."}}', NULL),
('3c97e597-1d77-5236-b9c1-83a572ae1238', '00000000-0000-0000-0000-000000000001', 'The Orphaned Child', 'A young soul without family, seeking belonging and purpose in a harsh world.', 'story', 'protagonist', 'Introduce to create sympathy or when exploring themes of family and identity.', '{"en":{"name":"The Orphaned Child","description":"A young soul without family, seeking belonging and purpose in a harsh world.","usage_examples":"Introduce to create sympathy or when exploring themes of family and identity."},"ru":{"name":"Сирота","description":"Юная душа без семьи, ищущая принадлежности и цели в суровом мире.","usage_examples":"Вводите, чтобы вызвать сочувствие или при исследовании тем семьи и идентичности."},"ua":{"name":"Сирота","description":"Юна душа без сім''ї, що шукає приналежності та мети в суворому світі.","usage_examples":"Вводьте, щоб викликати співчуття або при дослідженні тем сім''ї та ідентичності."}}', NULL),
('16a1e96c-53dd-5e49-b6f5-f842134e3ae5', '00000000-0000-0000-0000-000000000001', 'The Exiled Prince', 'Royalty cast out from their kingdom, seeking redemption or revenge.', 'story', 'protagonist', 'Use when introducing political intrigue or a character with a claim to power.', '{"en":{"name":"The Exiled Prince","description":"Royalty cast out from their kingdom, seeking redemption or revenge.","usage_examples":"Use when introducing political intrigue or a character with a claim to power."},"ru":{"name":"Изгнанный принц","description":"Член королевской семьи, изгнанный из своего королевства, ищущий искупления или мести.","usage_examples":"Используйте при введении политических интриг или персонажа с претензией на власть."},"ua":{"name":"Вигнаний принц","description":"Член королівської сім''ї, вигнаний зі свого королівства, що шукає спокути або помсти.","usage_examples":"Використовуйте при введенні політичних інтриг або персонажа з претензією на владу."}}', NULL),
('5bffa45c-c1bd-5611-835c-c57f2244c194', '00000000-0000-0000-0000-000000000001', 'The Brave Farmhand', 'A simple worker with extraordinary courage hidden beneath an ordinary exterior.', 'story', 'protagonist', 'Play to show that heroism can come from anywhere, not just nobility.', '{"en":{"name":"The Brave Farmhand","description":"A simple worker with extraordinary courage hidden beneath an ordinary exterior.","usage_examples":"Play to show that heroism can come from anywhere, not just nobility."},"ru":{"name":"Храбрый батрак","description":"Простой работник с необычайной храбростью, скрытой под обычной внешностью.","usage_examples":"Играйте, чтобы показать, что героизм может прийти откуда угодно, не только от знати."},"ua":{"name":"Хоробрий наймит","description":"Простий працівник з надзвичайною хоробрістю, прихованою під звичайною зовнішністю.","usage_examples":"Грайте, щоб показати, що героїзм може прийти звідки завгодно, не тільки від знаті."}}', NULL),
('0c5f7c2b-5b49-5562-89eb-becde058c4c7', '00000000-0000-0000-0000-000000000001', 'The Cursed Wanderer', 'A traveler bearing a terrible curse, seeking either a cure or acceptance.', 'story', 'protagonist', 'Introduce when adding mystery or when a character needs a dark secret.', '{"en":{"name":"The Cursed Wanderer","description":"A traveler bearing a terrible curse, seeking either a cure or acceptance.","usage_examples":"Introduce when adding mystery or when a character needs a dark secret."},"ru":{"name":"Проклятый странник","description":"Путешественник, несущий ужасное проклятие, ищущий либо исцеления, либо принятия.","usage_examples":"Вводите, когда добавляете тайну или когда персонажу нужен темный секрет."},"ua":{"name":"Проклятий мандрівник","description":"Мандрівник, що несе жахливе прокляття, шукає або зцілення, або прийняття.","usage_examples":"Вводьте, коли додаєте таємницю або коли персонажу потрібен темний секрет."}}', NULL),
('64429f32-ce4a-5350-8b29-873338b2daf7', '00000000-0000-0000-0000-000000000001', 'The Silent Guardian', 'A protector who watches from the shadows, speaking rarely but acting decisively.', 'story', 'protagonist', 'Use for mysterious protector figures or when actions speak louder than words.', '{"en":{"name":"The Silent Guardian","description":"A protector who watches from the shadows, speaking rarely but acting decisively.","usage_examples":"Use for mysterious protector figures or when actions speak louder than words."},"ru":{"name":"Безмолвный страж","description":"Защитник, наблюдающий из теней, редко говорящий, но действующий решительно.","usage_examples":"Используйте для таинственных фигур защитников или когда действия говорят громче слов."},"ua":{"name":"Мовчазний вартий","description":"Захисник, що спостерігає з тіней, рідко говорить, але діє рішуче.","usage_examples":"Використовуйте для таємничих фігур захисників або коли дії говорять голосніше слів."}}', NULL),
('ae218b6c-81e3-5ddb-978a-6ffd6e8e22fc', '00000000-0000-0000-0000-000000000001', 'The Clever Thief', 'A cunning rogue who steals not just treasures, but also hearts and secrets.', 'story', 'protagonist', 'Play when wit and stealth are needed, or to add moral complexity.', '{"en":{"name":"The Clever Thief","description":"A cunning rogue who steals not just treasures, but also hearts and secrets.","usage_examples":"Play when wit and stealth are needed, or to add moral complexity."},"ru":{"name":"Хитрый вор","description":"Ловкий плут, крадущий не только сокровища, но и сердца и секреты.","usage_examples":"Играйте, когда нужны остроумие и скрытность, или чтобы добавить моральной сложности."},"ua":{"name":"Хитрий злодій","description":"Спритний шахрай, що краде не тільки скарби, а й серця і секрети.","usage_examples":"Грайте, коли потрібні дотепність і скритність, або щоб додати моральної складності."}}', NULL),
('db26b0e5-1d9d-55e1-9643-6e932de3f398', '00000000-0000-0000-0000-000000000001', 'The Loyal Companion', 'A steadfast friend who will never abandon their allies, no matter the cost.', 'story', 'protagonist', 'Introduce to strengthen bonds between characters or show unwavering friendship.', '{"en":{"name":"The Loyal Companion","description":"A steadfast friend who will never abandon their allies, no matter the cost.","usage_examples":"Introduce to strengthen bonds between characters or show unwavering friendship."},"ru":{"name":"Верный спутник","description":"Непоколебимый друг, который никогда не бросит своих союзников, чего бы это ни стоило.","usage_examples":"Вводите, чтобы укрепить связи между персонажами или показать непоколебимую дружбу."},"ua":{"name":"Вірний супутник","description":"Непохитний друг, який ніколи не кине своїх союзників, чого б це не коштувало.","usage_examples":"Вводьте, щоб зміцнити зв''язки між персонажами або показати непохитну дружбу."}}', NULL),
('f0cdc31a-68be-51fe-8257-3ae9bedb156f', '00000000-0000-0000-0000-000000000001', 'The Talking Animal', 'A beast with the gift of speech, offering wisdom, humor, or unexpected insight.', 'story', 'protagonist', 'Use to add whimsy or when nature itself needs a voice.', '{"en":{"name":"The Talking Animal","description":"A beast with the gift of speech, offering wisdom, humor, or unexpected insight.","usage_examples":"Use to add whimsy or when nature itself needs a voice."},"ru":{"name":"Говорящее животное","description":"Зверь с даром речи, предлагающий мудрость, юмор или неожиданное прозрение.","usage_examples":"Используйте, чтобы добавить причудливости или когда самой природе нужен голос."},"ua":{"name":"Тварина, що говорить","description":"Звір з даром мови, що пропонує мудрість, гумор або несподіване прозріння.","usage_examples":"Використовуйте, щоб додати химерності або коли самій природі потрібен голос."}}', NULL),
('e640a7bb-d90a-5fd6-ab7a-7b38954fa610', '00000000-0000-0000-0000-000000000001', 'The Wise Mentor', 'An experienced guide who teaches and prepares the hero for their journey.', 'story', 'protagonist', 'Play when the hero needs guidance or when wisdom must be passed down.', '{"en":{"name":"The Wise Mentor","description":"An experienced guide who teaches and prepares the hero for their journey.","usage_examples":"Play when the hero needs guidance or when wisdom must be passed down."},"ru":{"name":"Мудрый наставник","description":"Опытный проводник, который учит и готовит героя к его путешествию.","usage_examples":"Играйте, когда герою нужно руководство или когда мудрость должна быть передана."},"ua":{"name":"Мудрий наставник","description":"Досвідчений провідник, який вчить і готує героя до його подорожі.","usage_examples":"Грайте, коли герою потрібне керівництво або коли мудрість повинна бути передана."}}', NULL),
('7d02b4ce-a708-580c-8e8e-61bbd95ff99b', '00000000-0000-0000-0000-000000000001', 'The Retired Knight', 'A warrior who hung up their sword, but may be called to fight once more.', 'story', 'protagonist', 'Introduce when experience is needed or to explore themes of aging and purpose.', '{"en":{"name":"The Retired Knight","description":"A warrior who hung up their sword, but may be called to fight once more.","usage_examples":"Introduce when experience is needed or to explore themes of aging and purpose."},"ru":{"name":"Отставной рыцарь","description":"Воин, повесивший свой меч, но который может быть призван сражаться снова.","usage_examples":"Вводите, когда нужен опыт или для исследования тем старения и предназначения."},"ua":{"name":"Лицар у відставці","description":"Воїн, що повісив свій меч, але який може бути покликаний битися знову.","usage_examples":"Вводьте, коли потрібен досвід або для дослідження тем старіння і призначення."}}', NULL),
('17279a9b-b646-50b3-b343-0d64880000f5', '00000000-0000-0000-0000-000000000001', 'The Rebellious Heir', 'A successor who rejects tradition and forges their own path.', 'story', 'protagonist', 'Use when challenging authority or exploring generational conflict.', '{"en":{"name":"The Rebellious Heir","description":"A successor who rejects tradition and forges their own path.","usage_examples":"Use when challenging authority or exploring generational conflict."},"ru":{"name":"Мятежный наследник","description":"Преемник, отвергающий традиции и прокладывающий свой собственный путь.","usage_examples":"Используйте, когда бросаете вызов власти или исследуете конфликт поколений."},"ua":{"name":"Бунтівний спадкоємець","description":"Наступник, що відкидає традиції і прокладає свій власний шлях.","usage_examples":"Використовуйте, коли кидаєте виклик владі або досліджуєте конфлікт поколінь."}}', NULL),
('6e0f501e-7d56-5885-9eb3-8b9d723f646a', '00000000-0000-0000-0000-000000000001', 'The Seer with No Eyes', 'A blind prophet who sees truths others cannot perceive.', 'story', 'protagonist', 'Play when prophecy or hidden knowledge becomes important.', '{"en":{"name":"The Seer with No Eyes","description":"A blind prophet who sees truths others cannot perceive.","usage_examples":"Play when prophecy or hidden knowledge becomes important."},"ru":{"name":"Слепой провидец","description":"Слепой пророк, видящий истины, которые другие не могут воспринять.","usage_examples":"Играйте, когда пророчество или скрытое знание становятся важными."},"ua":{"name":"Сліпий провидець","description":"Сліпий пророк, що бачить істини, які інші не можуть сприйняти.","usage_examples":"Грайте, коли пророцтво або приховане знання стають важливими."}}', NULL),
('c0b6ad30-dde2-5bf3-a84a-07e9042b0a66', '00000000-0000-0000-0000-000000000001', 'The Apprentice Mage', 'A young magic user still learning to control their growing powers.', 'story', 'protagonist', 'Introduce when magic goes awry or when potential must be nurtured.', '{"en":{"name":"The Apprentice Mage","description":"A young magic user still learning to control their growing powers.","usage_examples":"Introduce when magic goes awry or when potential must be nurtured."},"ru":{"name":"Ученик мага","description":"Юный маг, все еще учащийся контролировать свои растущие силы.","usage_examples":"Вводите, когда магия идет наперекосяк или когда потенциал нужно взращивать."},"ua":{"name":"Учень мага","description":"Юний маг, що все ще вчиться контролювати свої зростаючі сили.","usage_examples":"Вводьте, коли магія йде шкереберть або коли потенціал потрібно плекати."}}', NULL),
('90940b35-eb69-5b26-873e-6a97ae3df9a6', '00000000-0000-0000-0000-000000000001', 'The Grizzled Mercenary', 'A battle-hardened soldier who fights for coin, but may find a cause worth dying for.', 'story', 'protagonist', 'Use to add cynicism that can transform into idealism.', '{"en":{"name":"The Grizzled Mercenary","description":"A battle-hardened soldier who fights for coin, but may find a cause worth dying for.","usage_examples":"Use to add cynicism that can transform into idealism."},"ru":{"name":"Седой наемник","description":"Закаленный в боях солдат, сражающийся за монету, но который может найти дело, за которое стоит умереть.","usage_examples":"Используйте, чтобы добавить цинизма, который может превратиться в идеализм."},"ua":{"name":"Сивий найманець","description":"Загартований у боях солдат, що б''ється за монету, але який може знайти справу, за яку варто померти.","usage_examples":"Використовуйте, щоб додати цинізму, який може перетворитися на ідеалізм."}}', NULL),
('7bfb0b4f-f5e0-5f4f-8b08-8a7d3546a387', '00000000-0000-0000-0000-000000000001', 'The Fool Who Knows Too Much', 'A jester or simpleton who speaks uncomfortable truths disguised as jokes.', 'story', 'protagonist', 'Play when truth needs to be spoken or when wisdom comes from unexpected sources.', '{"en":{"name":"The Fool Who Knows Too Much","description":"A jester or simpleton who speaks uncomfortable truths disguised as jokes.","usage_examples":"Play when truth needs to be spoken or when wisdom comes from unexpected sources."},"ru":{"name":"Шут, знающий слишком много","description":"Шут или простак, говорящий неудобные истины, замаскированные под шутки.","usage_examples":"Играйте, когда правда должна быть сказана или когда мудрость исходит из неожиданных источников."},"ua":{"name":"Блазень, що знає забагато","description":"Блазень або простак, що говорить незручні істини, замасковані під жарти.","usage_examples":"Грайте, коли правда повинна бути сказана або коли мудрість виходить з несподіваних джерел."}}', NULL),
('fd1512b5-eb7b-5964-92ea-0e7bb8d35c93', '00000000-0000-0000-0000-000000000001', 'The Shape-shifting Ally', 'A friend who can change their form, hiding their true nature.', 'story', 'protagonist', 'Introduce to add mystery or when identity becomes fluid.', '{"en":{"name":"The Shape-shifting Ally","description":"A friend who can change their form, hiding their true nature.","usage_examples":"Introduce to add mystery or when identity becomes fluid."},"ru":{"name":"Оборотень-союзник","description":"Друг, способный менять свою форму, скрывая свою истинную природу.","usage_examples":"Вводите, чтобы добавить тайну или когда идентичность становится изменчивой."},"ua":{"name":"Перевертень-союзник","description":"Друг, здатний змінювати свою форму, приховуючи свою справжню природу.","usage_examples":"Вводьте, щоб додати таємницю або коли ідентичність стає мінливою."}}', NULL),
('193429b4-ce96-587c-923b-b4ffa3b58e6f', '00000000-0000-0000-0000-000000000001', 'The Ghost of a Friend', 'A departed companion who returns to offer aid from beyond death.', 'story', 'protagonist', 'Use when the past haunts the present or when closure is needed.', '{"en":{"name":"The Ghost of a Friend","description":"A departed companion who returns to offer aid from beyond death.","usage_examples":"Use when the past haunts the present or when closure is needed."},"ru":{"name":"Призрак друга","description":"Ушедший спутник, возвращающийся, чтобы предложить помощь из-за черты смерти.","usage_examples":"Используйте, когда прошлое преследует настоящее или когда нужно закрыть гештальт."},"ua":{"name":"Привид друга","description":"Померлий супутник, що повертається, щоб запропонувати допомогу з-за межі смерті.","usage_examples":"Використовуйте, коли минуле переслідує сьогодення або коли потрібно закрити гештальт."}}', NULL),
('e534d349-c1ef-5f19-a4b3-6c34534e3e77', '00000000-0000-0000-0000-000000000001', 'The Forgotten Twin', 'A sibling lost or hidden, whose return changes everything.', 'story', 'protagonist', 'Play to introduce shocking revelations or family drama.', '{"en":{"name":"The Forgotten Twin","description":"A sibling lost or hidden, whose return changes everything.","usage_examples":"Play to introduce shocking revelations or family drama."},"ru":{"name":"Забытый близнец","description":"Потерянный или спрятанный брат/сестра, чье возвращение меняет все.","usage_examples":"Играйте, чтобы ввести шокирующие откровения или семейную драму."},"ua":{"name":"Забутий близнюк","description":"Втрачений або захований брат/сестра, чиє повернення змінює все.","usage_examples":"Грайте, щоб ввести шокуючі одкровення або сімейну драму."}}', NULL),
('f3e48669-c618-5f43-b058-360a6a003227', '00000000-0000-0000-0000-000000000001', 'The Healer with a Secret', 'One who mends wounds but carries a hidden burden or dark knowledge.', 'story', 'protagonist', 'Introduce when healing is needed or when secrets must be revealed.', '{"en":{"name":"The Healer with a Secret","description":"One who mends wounds but carries a hidden burden or dark knowledge.","usage_examples":"Introduce when healing is needed or when secrets must be revealed."},"ru":{"name":"Целитель с тайной","description":"Тот, кто лечит раны, но несет скрытое бремя или темное знание.","usage_examples":"Вводите, когда нужно исцеление или когда секреты должны быть раскрыты."},"ua":{"name":"Цілитель з таємницею","description":"Той, хто лікує рани, але несе прихований тягар або темне знання.","usage_examples":"Вводьте, коли потрібне зцілення або коли секрети повинні бути розкриті."}}', NULL),
('b71ba3f1-1f06-5d67-bba6-4fc00e51a4ec', '00000000-0000-0000-0000-000000000001', 'The Bard Who Can''t Lie', 'A storyteller cursed or blessed to speak only truth through song.', 'story', 'protagonist', 'Use when truth must be revealed or when music drives the narrative.', '{"en":{"name":"The Bard Who Can''t Lie","description":"A storyteller cursed or blessed to speak only truth through song.","usage_examples":"Use when truth must be revealed or when music drives the narrative."},"ru":{"name":"Бард, не умеющий лгать","description":"Рассказчик, проклятый или благословленный говорить только правду через песню.","usage_examples":"Используйте, когда правда должна быть раскрыта или когда музыка движет повествование."},"ua":{"name":"Бард, що не вміє брехати","description":"Оповідач, проклятий або благословенний говорити тільки правду через пісню.","usage_examples":"Використовуйте, коли правда повинна бути розкрита або коли музика рухає розповідь."}}', NULL),
('0ad1fb08-a24e-5b0f-af39-e8bc040360b4', '00000000-0000-0000-0000-000000000001', 'The Last of Their Kind', 'The final survivor of a lost people, carrying their legacy alone.', 'story', 'protagonist', 'Play to explore themes of extinction, preservation, and loneliness.', '{"en":{"name":"The Last of Their Kind","description":"The final survivor of a lost people, carrying their legacy alone.","usage_examples":"Play to explore themes of extinction, preservation, and loneliness."},"ru":{"name":"Последний из своего рода","description":"Последний выживший из исчезнувшего народа, несущий их наследие в одиночку.","usage_examples":"Играйте для исследования тем вымирания, сохранения и одиночества."},"ua":{"name":"Останній зі свого роду","description":"Останній, хто вижив зі зниклого народу, що несе їх спадщину наодинці.","usage_examples":"Грайте для дослідження тем вимирання, збереження та самотності."}}', NULL),
('96873392-1c25-5d0d-bc3d-b6aec4d00d56', '00000000-0000-0000-0000-000000000001', 'The Child of Prophecy', 'A young one foretold to bring great change, for good or ill.', 'story', 'protagonist', 'Introduce when destiny and innocence collide.', '{"en":{"name":"The Child of Prophecy","description":"A young one foretold to bring great change, for good or ill.","usage_examples":"Introduce when destiny and innocence collide."},"ru":{"name":"Дитя пророчества","description":"Юное создание, которому предсказано принести великие перемены, к добру или к худу.","usage_examples":"Вводите, когда судьба и невинность сталкиваются."},"ua":{"name":"Дитя пророцтва","description":"Юне створіння, якому передбачено принести великі зміни, до добра чи до лиха.","usage_examples":"Вводьте, коли доля і невинність стикаються."}}', NULL),
('6440502b-b2c0-5f60-b589-bd01ec4c8fc3', '00000000-0000-0000-0000-000000000001', 'The Time-Lost Stranger', 'Someone displaced from their era, struggling to understand a changed world.', 'story', 'protagonist', 'Use when exploring themes of change, nostalgia, or fish-out-of-water scenarios.', '{"en":{"name":"The Time-Lost Stranger","description":"Someone displaced from their era, struggling to understand a changed world.","usage_examples":"Use when exploring themes of change, nostalgia, or fish-out-of-water scenarios."},"ru":{"name":"Странник, потерянный во времени","description":"Кто-то, перемещенный из своей эпохи, пытающийся понять изменившийся мир.","usage_examples":"Используйте при исследовании тем перемен, ностальгии или сценариев «не в своей тарелке»."},"ua":{"name":"Мандрівник, загублений у часі","description":"Хтось, переміщений зі своєї епохи, що намагається зрозуміти світ, який змінився.","usage_examples":"Використовуйте при дослідженні тем змін, ностальгії або сценаріїв «не в своїй тарілці»."}}', NULL),
('cd3e990b-da3e-5ba7-bed2-bc3184149747', '00000000-0000-0000-0000-000000000001', 'The Inventor of Impossible Things', 'A creator who defies the laws of nature with their ingenious devices.', 'story', 'protagonist', 'Play when innovation is needed or when science meets magic.', '{"en":{"name":"The Inventor of Impossible Things","description":"A creator who defies the laws of nature with their ingenious devices.","usage_examples":"Play when innovation is needed or when science meets magic."},"ru":{"name":"Изобретатель невозможного","description":"Творец, бросающий вызов законам природы своими гениальными устройствами.","usage_examples":"Играйте, когда нужны инновации или когда наука встречается с магией."},"ua":{"name":"Винахідник неможливого","description":"Творець, що кидає виклик законам природи своїми геніальними пристроями.","usage_examples":"Грайте, коли потрібні інновації або коли наука зустрічається з магією."}}', NULL),
('6681a78d-d24a-57c4-bb1c-1bc072133b18', '00000000-0000-0000-0000-000000000001', 'The One Who Remembers', 'A keeper of memories in a world that has forgotten its past.', 'story', 'protagonist', 'Introduce when history is important or when the past must be reclaimed.', '{"en":{"name":"The One Who Remembers","description":"A keeper of memories in a world that has forgotten its past.","usage_examples":"Introduce when history is important or when the past must be reclaimed."},"ru":{"name":"Тот, кто помнит","description":"Хранитель воспоминаний в мире, который забыл свое прошлое.","usage_examples":"Вводите, когда история важна или когда прошлое должно быть возвращено."},"ua":{"name":"Той, хто пам''ятає","description":"Зберігач спогадів у світі, який забув своє минуле.","usage_examples":"Вводьте, коли історія важлива або коли минуле повинно бути повернуто."}}', NULL),
('d04077f2-2f0d-5719-b131-a19aa7fa8878', '00000000-0000-0000-0000-000000000001', 'The Peacemaker', 'One who seeks harmony and understanding between warring factions.', 'story', 'protagonist', 'Use when conflict needs resolution or when diplomacy is the answer.', '{"en":{"name":"The Peacemaker","description":"One who seeks harmony and understanding between warring factions.","usage_examples":"Use when conflict needs resolution or when diplomacy is the answer."},"ru":{"name":"Миротворец","description":"Тот, кто ищет гармонии и понимания между враждующими фракциями.","usage_examples":"Используйте, когда конфликт требует разрешения или когда дипломатия — это ответ."},"ua":{"name":"Миротворець","description":"Той, хто шукає гармонії та розуміння між ворогуючими фракціями.","usage_examples":"Використовуйте, коли конфлікт вимагає вирішення або коли дипломатія — це відповідь."}}', NULL),
('f040cf7e-fa78-5e33-bea8-bc156eef24bd', '00000000-0000-0000-0000-000000000001', 'The Reluctant Leader', 'Someone thrust into command who doubts their ability to lead.', 'story', 'protagonist', 'Play when leadership is needed but confidence is lacking.', '{"en":{"name":"The Reluctant Leader","description":"Someone thrust into command who doubts their ability to lead.","usage_examples":"Play when leadership is needed but confidence is lacking."},"ru":{"name":"Неохотный лидер","description":"Кто-то, вынужденный командовать, кто сомневается в своей способности вести за собой.","usage_examples":"Играйте, когда нужно лидерство, но не хватает уверенности."},"ua":{"name":"Неохочий лідер","description":"Хтось, змушений командувати, хто сумнівається у своїй здатності вести за собою.","usage_examples":"Грайте, коли потрібне лідерство, але не вистачає впевненості."}}', NULL),
('f701c0c4-14c7-5a4e-8d5f-1ad6addffe59', '00000000-0000-0000-0000-000000000001', 'The Dreamer Who Dared', 'A visionary who pursues impossible dreams against all odds.', 'story', 'protagonist', 'Introduce when hope and ambition drive the story forward.', '{"en":{"name":"The Dreamer Who Dared","description":"A visionary who pursues impossible dreams against all odds.","usage_examples":"Introduce when hope and ambition drive the story forward."},"ru":{"name":"Мечтатель, который осмелился","description":"Визионер, преследующий невозможные мечты вопреки всему.","usage_examples":"Вводите, когда надежда и амбиции двигают историю вперед."},"ua":{"name":"Мрійник, що наважився","description":"Візіонер, що переслідує неможливі мрії всупереч усьому.","usage_examples":"Вводьте, коли надія і амбіції рухають історію вперед."}}', NULL)
INSERT INTO "public"."cards" (id, deck_id, name, description, type, category, usage_examples, translations, image_url) VALUES
('b2731894-91d7-52f4-a5ed-324bf4a6d038', '00000000-0000-0000-0000-000000000001', 'The Shadow King', 'A dark ruler who commands from the shadows, spreading fear and corruption.', 'story', 'antagonist', 'Use as a primary villain or when introducing political darkness.', '{"en":{"name":"The Shadow King","description":"A dark ruler who commands from the shadows, spreading fear and corruption.","usage_examples":"Use as a primary villain or when introducing political darkness."},"ru":{"name":"Король Теней","description":"Темный правитель, командующий из теней, распространяющий страх и коррупцию.","usage_examples":"Используйте как главного злодея или при введении политической тьмы."},"ua":{"name":"Король Тіней","description":"Темний правитель, що командує з тіней, поширюючи страх і корупцію.","usage_examples":"Використовуйте як головного лиходія або при введенні політичної темряви."}}', NULL),
('0d22d1c6-c135-5652-b0bd-55f49e935c76', '00000000-0000-0000-0000-000000000001', 'The Betrayer Within', 'A trusted ally who reveals their true treacherous nature at a critical moment.', 'story', 'antagonist', 'Play when trust is broken or when revealing a shocking betrayal.', '{"en":{"name":"The Betrayer Within","description":"A trusted ally who reveals their true treacherous nature at a critical moment.","usage_examples":"Play when trust is broken or when revealing a shocking betrayal."},"ru":{"name":"Предатель внутри","description":"Доверенный союзник, раскрывающий свою истинную предательскую натуру в критический момент.","usage_examples":"Играйте, когда доверие нарушено или при раскрытии шокирующего предательства."},"ua":{"name":"Зрадник всередині","description":"Довірений союзник, що розкриває свою справжню зрадницьку натуру в критичний момент.","usage_examples":"Грайте, коли довіра порушена або при розкритті шокуючої зради."}}', NULL),
('677312b3-1396-5d08-abfc-d3eacbebbcd3', '00000000-0000-0000-0000-000000000001', 'The Cursed Beast', 'A monster born from magic or tragedy, driven by instinct and suffering.', 'story', 'antagonist', 'Introduce when facing a tragic villain or a force of nature.', '{"en":{"name":"The Cursed Beast","description":"A monster born from magic or tragedy, driven by instinct and suffering.","usage_examples":"Introduce when facing a tragic villain or a force of nature."},"ru":{"name":"Проклятый зверь","description":"Монстр, рожденный магией или трагедией, движимый инстинктом и страданием.","usage_examples":"Вводите, когда сталкиваетесь с трагическим злодеем или силой природы."},"ua":{"name":"Проклятий звір","description":"Монстр, народжений магією або трагедією, керований інстинктом і стражданням.","usage_examples":"Вводьте, коли стикаєтеся з трагічним лиходієм або силою природи."}}', NULL),
('ba623e06-072f-569c-a410-41bdd2bfff64', '00000000-0000-0000-0000-000000000001', 'The False Prophet', 'A charismatic deceiver who leads followers astray with lies disguised as truth.', 'story', 'antagonist', 'Use when exploring themes of manipulation and false faith.', '{"en":{"name":"The False Prophet","description":"A charismatic deceiver who leads followers astray with lies disguised as truth.","usage_examples":"Use when exploring themes of manipulation and false faith."},"ru":{"name":"Лжепророк","description":"Харизматичный обманщик, вводящий последователей в заблуждение ложью, замаскированной под правду.","usage_examples":"Используйте при исследовании тем манипуляции и ложной веры."},"ua":{"name":"Лжепророк","description":"Харизматичний ошуканець, що вводить послідовників в оману брехнею, замаскованою під правду.","usage_examples":"Використовуйте при дослідженні тем маніпуляції та фальшивої віри."}}', NULL),
('17511ef3-cb34-56bf-bf94-5e42c49d9dfc', '00000000-0000-0000-0000-000000000001', 'The Puppetmaster', 'A manipulator who controls others from behind the scenes.', 'story', 'antagonist', 'Play when revealing hidden control or conspiracy.', '{"en":{"name":"The Puppetmaster","description":"A manipulator who controls others from behind the scenes.","usage_examples":"Play when revealing hidden control or conspiracy."},"ru":{"name":"Кукловод","description":"Манипулятор, управляющий другими из-за кулис.","usage_examples":"Играйте, когда раскрываете скрытый контроль или заговор."},"ua":{"name":"Ляльковод","description":"Маніпулятор, що керує іншими з-за лаштунків.","usage_examples":"Грайте, коли розкриваєте прихований контроль або змову."}}', NULL),
('e29a1084-31b0-5c54-85dc-44fbcf622c2f', '00000000-0000-0000-0000-000000000001', 'The Ancient Evil', 'A primordial force of darkness that predates civilization itself.', 'story', 'antagonist', 'Introduce when facing ultimate evil or ancient threats.', '{"en":{"name":"The Ancient Evil","description":"A primordial force of darkness that predates civilization itself.","usage_examples":"Introduce when facing ultimate evil or ancient threats."},"ru":{"name":"Древнее зло","description":"Изначальная сила тьмы, предшествующая самой цивилизации.","usage_examples":"Вводите, когда сталкиваетесь с абсолютным злом или древними угрозами."},"ua":{"name":"Стародавнє зло","description":"Первісна сила темряви, що передує самій цивілізації.","usage_examples":"Вводьте, коли стикаєтеся з абсолютним злом або стародавніми загрозами."}}', NULL),
('6c340805-76b8-5699-87e1-ccfa758b0eec', '00000000-0000-0000-0000-000000000001', 'The Smiling Assassin', 'A killer who wears a friendly face while plotting murder.', 'story', 'antagonist', 'Use when danger hides behind charm.', '{"en":{"name":"The Smiling Assassin","description":"A killer who wears a friendly face while plotting murder.","usage_examples":"Use when danger hides behind charm."},"ru":{"name":"Улыбающийся убийца","description":"Убийца, носящий дружелюбное лицо, замышляя убийство.","usage_examples":"Используйте, когда опасность скрывается за обаянием."},"ua":{"name":"Усміхнений вбивця","description":"Вбивця, що носить доброзичливе обличчя, задумуючи вбивство.","usage_examples":"Використовуйте, коли небезпека ховається за чарівністю."}}', NULL),
('f2d82e42-fed8-574d-b911-24ca48d73db2', '00000000-0000-0000-0000-000000000001', 'The Tyrant Queen', 'A ruthless monarch who rules through fear and absolute power.', 'story', 'antagonist', 'Play when introducing oppressive authority.', '{"en":{"name":"The Tyrant Queen","description":"A ruthless monarch who rules through fear and absolute power.","usage_examples":"Play when introducing oppressive authority."},"ru":{"name":"Королева-тиран","description":"Безжалостный монарх, правящий через страх и абсолютную власть.","usage_examples":"Играйте, когда вводите деспотичную власть."},"ua":{"name":"Королева-тиран","description":"Безжалісний монарх, що править через страх і абсолютну владу.","usage_examples":"Грайте, коли вводите деспотичну владу."}}', NULL),
('d5dcc543-efa5-5d32-8334-cdd08cadae98', '00000000-0000-0000-0000-000000000001', 'The Whispering Mask', 'A mysterious figure whose true face is never seen, speaking in riddles and lies.', 'story', 'antagonist', 'Introduce when mystery and deception are key.', '{"en":{"name":"The Whispering Mask","description":"A mysterious figure whose true face is never seen, speaking in riddles and lies.","usage_examples":"Introduce when mystery and deception are key."},"ru":{"name":"Шепчущая маска","description":"Таинственная фигура, чье истинное лицо никогда не видно, говорящая загадками и ложью.","usage_examples":"Вводите, когда тайна и обман являются ключевыми."},"ua":{"name":"Маска, що шепоче","description":"Таємнича фігура, чиє справжнє обличчя ніколи не видно, що говорить загадками і брехнею.","usage_examples":"Вводьте, коли таємниця і обман є ключовими."}}', NULL),
('b72058c9-acd8-557d-9f11-d34ad23a4485', '00000000-0000-0000-0000-000000000001', 'The Mirror Doppelgänger', 'An evil twin or duplicate that mimics and corrupts.', 'story', 'antagonist', 'Use when exploring identity or facing oneself.', '{"en":{"name":"The Mirror Doppelgänger","description":"An evil twin or duplicate that mimics and corrupts.","usage_examples":"Use when exploring identity or facing oneself."},"ru":{"name":"Зеркальный двойник","description":"Злой близнец или дубликат, который подражает и развращает.","usage_examples":"Используйте при исследовании идентичности или столкновении с самим собой."},"ua":{"name":"Дзеркальний двійник","description":"Злий близнюк або дублікат, який наслідує і розбещує.","usage_examples":"Використовуйте при дослідженні ідентичності або зіткненні з самим собою."}}', NULL),
('a44903a0-20b5-56a1-ad46-ada131918fd5', '00000000-0000-0000-0000-000000000001', 'The Corrupted Mentor', 'A once-wise teacher who has fallen to darkness and now corrupts others.', 'story', 'antagonist', 'Play when trust in authority is shattered.', '{"en":{"name":"The Corrupted Mentor","description":"A once-wise teacher who has fallen to darkness and now corrupts others.","usage_examples":"Play when trust in authority is shattered."},"ru":{"name":"Развращенный наставник","description":"Некогда мудрый учитель, павший во тьму и теперь развращающий других.","usage_examples":"Играйте, когда вера в авторитеты разрушена."},"ua":{"name":"Розбещений наставник","description":"Колись мудрий вчитель, що впав у темряву і тепер розбещує інших.","usage_examples":"Грайте, коли віра в авторитети зруйнована."}}', NULL),
('44a503b9-e4cf-5fc6-8415-8710f3a02718', '00000000-0000-0000-0000-000000000001', 'The Unseen Watcher', 'An entity that observes from the darkness, its motives unknown.', 'story', 'antagonist', 'Introduce when paranoia and surveillance are themes.', '{"en":{"name":"The Unseen Watcher","description":"An entity that observes from the darkness, its motives unknown.","usage_examples":"Introduce when paranoia and surveillance are themes."},"ru":{"name":"Невидимый наблюдатель","description":"Сущность, наблюдающая из темноты, чьи мотивы неизвестны.","usage_examples":"Вводите, когда паранойя и наблюдение являются темами."},"ua":{"name":"Невидимий спостерігач","description":"Сутність, що спостерігає з темряви, чиї мотиви невідомі.","usage_examples":"Вводьте, коли параноя і спостереження є темами."}}', NULL),
('c165f726-51ae-53dd-81bd-d97d40f64884', '00000000-0000-0000-0000-000000000001', 'The Collector of Souls', 'A being that harvests life essence or spirits for dark purposes.', 'story', 'antagonist', 'Use when death and the afterlife are at stake.', '{"en":{"name":"The Collector of Souls","description":"A being that harvests life essence or spirits for dark purposes.","usage_examples":"Use when death and the afterlife are at stake."},"ru":{"name":"Собиратель душ","description":"Существо, собирающее жизненную эссенцию или духов для темных целей.","usage_examples":"Используйте, когда смерть и загробная жизнь на кону."},"ua":{"name":"Збирач душ","description":"Істота, що збирає життєву есенцію або духів для темних цілей.","usage_examples":"Використовуйте, коли смерть і потойбічне життя на кону."}}', NULL),
('6567d2f3-e4b7-5619-b346-940b6edd657b', '00000000-0000-0000-0000-000000000001', 'The Laughing Plague', 'A disease or curse that spreads madness and hysteria.', 'story', 'antagonist', 'Play when facing an epidemic or loss of sanity.', '{"en":{"name":"The Laughing Plague","description":"A disease or curse that spreads madness and hysteria.","usage_examples":"Play when facing an epidemic or loss of sanity."},"ru":{"name":"Смеющаяся чума","description":"Болезнь или проклятие, распространяющее безумие и истерию.","usage_examples":"Играйте, когда сталкиваетесь с эпидемией или потерей рассудка."},"ua":{"name":"Чума, що сміється","description":"Хвороба або прокляття, що поширює божевілля та істерію.","usage_examples":"Грайте, коли стикаєтеся з епідемією або втратою розуму."}}', NULL),
('416abe64-65a5-5b74-b55f-81238e52d61c', '00000000-0000-0000-0000-000000000001', 'The Eternal Duelist', 'A warrior who challenges all to combat, never satisfied, never defeated.', 'story', 'antagonist', 'Introduce when honor and combat are central.', '{"en":{"name":"The Eternal Duelist","description":"A warrior who challenges all to combat, never satisfied, never defeated.","usage_examples":"Introduce when honor and combat are central."},"ru":{"name":"Вечный дуэлянт","description":"Воин, бросающий вызов всем на бой, никогда не удовлетворенный, никогда не побежденный.","usage_examples":"Вводите, когда честь и бой являются центральными."},"ua":{"name":"Вічний дуелянт","description":"Воїн, що кидає виклик усім на бій, ніколи не задоволений, ніколи не переможений.","usage_examples":"Вводьте, коли честь і бій є центральними."}}', NULL),
('8bc14dfd-dace-5575-be46-1ef554003c53', '00000000-0000-0000-0000-000000000001', 'The Fallen Hero', 'A once-great champion who has become what they once fought against.', 'story', 'antagonist', 'Use to explore tragedy and the corruption of ideals.', '{"en":{"name":"The Fallen Hero","description":"A once-great champion who has become what they once fought against.","usage_examples":"Use to explore tragedy and the corruption of ideals."},"ru":{"name":"Падший герой","description":"Некогда великий чемпион, ставший тем, против чего он когда-то сражался.","usage_examples":"Используйте для исследования трагедии и коррупции идеалов."},"ua":{"name":"Полеглий герой","description":"Колись великий чемпіон, що став тим, проти чого він колись бився.","usage_examples":"Використовуйте для дослідження трагедії та корупції ідеалів."}}', NULL),
('cfd97f4a-e989-58b7-8de5-700ceaf15a7a', '00000000-0000-0000-0000-000000000001', 'The Living Storm', 'A sentient tempest that destroys without mercy or reason.', 'story', 'antagonist', 'Play when facing nature''s wrath personified.', '{"en":{"name":"The Living Storm","description":"A sentient tempest that destroys without mercy or reason.","usage_examples":"Play when facing nature''s wrath personified."},"ru":{"name":"Живая буря","description":"Разумная буря, уничтожающая без жалости и причины.","usage_examples":"Играйте, когда сталкиваетесь с олицетворенным гневом природы."},"ua":{"name":"Жива буря","description":"Розумна буря, що знищує без жалю і причини.","usage_examples":"Грайте, коли стикаєтеся з уособленим гнівом природи."}}', NULL),
('1fd909f1-d43c-5a19-a3e6-221ef8a91cdc', '00000000-0000-0000-0000-000000000001', 'The Hunger That Walks', 'An insatiable force that consumes everything in its path.', 'story', 'antagonist', 'Introduce when facing unstoppable consumption.', '{"en":{"name":"The Hunger That Walks","description":"An insatiable force that consumes everything in its path.","usage_examples":"Introduce when facing unstoppable consumption."},"ru":{"name":"Голод, что ходит","description":"Ненасытная сила, поглощающая все на своем пути.","usage_examples":"Вводите, когда сталкиваетесь с неостановимым потреблением."},"ua":{"name":"Голод, що ходить","description":"Ненаситна сила, що поглинає все на своєму шляху.","usage_examples":"Вводьте, коли стикаєтеся з невпинним споживанням."}}', NULL),
('ae89f771-a0c1-5afe-93f6-72637ab37d46', '00000000-0000-0000-0000-000000000001', 'The Forgotten God', 'A deity abandoned by worshippers, now seeking revenge or recognition.', 'story', 'antagonist', 'Use when exploring themes of faith and abandonment.', '{"en":{"name":"The Forgotten God","description":"A deity abandoned by worshippers, now seeking revenge or recognition.","usage_examples":"Use when exploring themes of faith and abandonment."},"ru":{"name":"Забытый бог","description":"Божество, покинутое верующими, теперь ищущее мести или признания.","usage_examples":"Используйте при исследовании тем веры и покинутости."},"ua":{"name":"Забутий бог","description":"Божество, покинуте віруючими, що тепер шукає помсти або визнання.","usage_examples":"Використовуйте при дослідженні тем віри та покинутості."}}', NULL),
('fe022bfe-9fbe-5ec2-91cc-de5a44b87f37', '00000000-0000-0000-0000-000000000001', 'The Bound Demon', 'An evil entity trapped but seeking freedom to wreak havoc.', 'story', 'antagonist', 'Play when dealing with ancient prisons and forbidden power.', '{"en":{"name":"The Bound Demon","description":"An evil entity trapped but seeking freedom to wreak havoc.","usage_examples":"Play when dealing with ancient prisons and forbidden power."},"ru":{"name":"Скованный демон","description":"Злая сущность, пойманная в ловушку, но ищущая свободы, чтобы сеять хаос.","usage_examples":"Играйте, когда имеете дело с древними тюрьмами и запретной силой."},"ua":{"name":"Скутий демон","description":"Зла сутність, спіймана в пастку, але шукає свободи, щоб сіяти хаос.","usage_examples":"Грайте, коли маєте справу зі стародавніми в''язницями та забороненою силою."}}', NULL),
('5c9375ec-901b-5df5-bae9-b24c9445b8fc', '00000000-0000-0000-0000-000000000001', 'The Voice in the Flames', 'A presence that speaks through fire, offering power at a terrible price.', 'story', 'antagonist', 'Introduce when temptation and deals with evil are themes.', '{"en":{"name":"The Voice in the Flames","description":"A presence that speaks through fire, offering power at a terrible price.","usage_examples":"Introduce when temptation and deals with evil are themes."},"ru":{"name":"Голос в огне","description":"Присутствие, говорящее через огонь, предлагающее силу за ужасную цену.","usage_examples":"Вводите, когда искушение и сделки со злом являются темами."},"ua":{"name":"Голос у вогні","description":"Присутність, що говорить через вогонь, пропонуючи силу за жахливу ціну.","usage_examples":"Вводьте, коли спокуса та угоди зі злом є темами."}}', NULL),
('d209547f-6f3e-5464-830c-707bdfe75f1f', '00000000-0000-0000-0000-000000000001', 'The One Who Knows Your Name', 'An entity with power over those whose true names it learns.', 'story', 'antagonist', 'Use when names and identity hold magical significance.', '{"en":{"name":"The One Who Knows Your Name","description":"An entity with power over those whose true names it learns.","usage_examples":"Use when names and identity hold magical significance."},"ru":{"name":"Тот, кто знает твое имя","description":"Сущность, имеющая власть над теми, чьи истинные имена она узнает.","usage_examples":"Используйте, когда имена и идентичность имеют магическое значение."},"ua":{"name":"Той, хто знає твоє ім''я","description":"Сутність, що має владу над тими, чиї справжні імена вона дізнається.","usage_examples":"Використовуйте, коли імена та ідентичність мають магічне значення."}}', NULL),
('02d4509f-667c-5214-b9d5-4bd34b8abc90', '00000000-0000-0000-0000-000000000001', 'The Clockwork Warden', 'A mechanical enforcer that follows its programming without mercy.', 'story', 'antagonist', 'Play when facing cold, logical opposition.', '{"en":{"name":"The Clockwork Warden","description":"A mechanical enforcer that follows its programming without mercy.","usage_examples":"Play when facing cold, logical opposition."},"ru":{"name":"Заводной страж","description":"Механический страж, следующий своей программе без жалости.","usage_examples":"Играйте, когда сталкиваетесь с холодным, логичным сопротивлением."},"ua":{"name":"Механічний вартий","description":"Механічний вартий, що слідує своїй програмі без жалю.","usage_examples":"Грайте, коли стикаєтеся з холодним, логічним опором."}}', NULL),
('44b61b86-4cad-5061-9789-83ac3b74701b', '00000000-0000-0000-0000-000000000001', 'The Beast Beneath the City', 'A monster lurking in the depths below civilization.', 'story', 'antagonist', 'Introduce when urban legends become real.', '{"en":{"name":"The Beast Beneath the City","description":"A monster lurking in the depths below civilization.","usage_examples":"Introduce when urban legends become real."},"ru":{"name":"Зверь под городом","description":"Монстр, скрывающийся в глубинах под цивилизацией.","usage_examples":"Вводите, когда городские легенды становятся реальностью."},"ua":{"name":"Звір під містом","description":"Монстр, що ховається в глибинах під цивілізацією.","usage_examples":"Вводьте, коли міські легенди стають реальністю."}}', NULL),
('42123995-b6a9-5259-aa2e-db9ea7e1510c', '00000000-0000-0000-0000-000000000001', 'The Curse of the Blood Moon', 'A recurring supernatural event that brings transformation and terror.', 'story', 'antagonist', 'Use when cycles and lunar magic are important.', '{"en":{"name":"The Curse of the Blood Moon","description":"A recurring supernatural event that brings transformation and terror.","usage_examples":"Use when cycles and lunar magic are important."},"ru":{"name":"Проклятие Кровавой Луны","description":"Повторяющееся сверхъестественное событие, приносящее трансформацию и ужас.","usage_examples":"Используйте, когда циклы и лунная магия важны."},"ua":{"name":"Прокляття Кривавого Місяця","description":"Надприродна подія, що повторюється, приносячи трансформацію та жах.","usage_examples":"Використовуйте, коли цикли та місячна магія важливі."}}', NULL),
('c83d99e7-9456-5117-aefe-157edcda38f4', '00000000-0000-0000-0000-000000000001', 'The Silent Inquisition', 'A secretive organization that hunts and judges in silence.', 'story', 'antagonist', 'Play when introducing persecution and witch hunts.', '{"en":{"name":"The Silent Inquisition","description":"A secretive organization that hunts and judges in silence.","usage_examples":"Play when introducing persecution and witch hunts."},"ru":{"name":"Безмолвная инквизиция","description":"Тайная организация, которая охотится и судит в тишине.","usage_examples":"Играйте, когда вводите преследование и охоту на ведьм."},"ua":{"name":"Мовчазна інквізиція","description":"Таємна організація, яка полює і судить в тиші.","usage_examples":"Грайте, коли вводите переслідування та полювання на відьом."}}', NULL),
('503c3da2-9b4a-5363-8018-1d3f136e1d09', '00000000-0000-0000-0000-000000000001', 'The Eyes in the Dark', 'Watchers from the shadows whose gaze brings madness.', 'story', 'antagonist', 'Introduce when paranoia and unseen threats loom.', '{"en":{"name":"The Eyes in the Dark","description":"Watchers from the shadows whose gaze brings madness.","usage_examples":"Introduce when paranoia and unseen threats loom."},"ru":{"name":"Глаза во тьме","description":"Наблюдатели из теней, чей взгляд приносит безумие.","usage_examples":"Вводите, когда нависают паранойя и невидимые угрозы."},"ua":{"name":"Очі в темряві","description":"Спостерігачі з тіней, чий погляд приносить божевілля.","usage_examples":"Вводьте, коли нависають параноя та невидимі загрози."}}', NULL),
('72d7725a-0281-55a5-868e-a6a6b17a92d0', '00000000-0000-0000-0000-000000000001', 'The Broken Oath', 'The consequence of a promise shattered, manifesting as a curse or entity.', 'story', 'antagonist', 'Use when vows and their breaking have power.', '{"en":{"name":"The Broken Oath","description":"The consequence of a promise shattered, manifesting as a curse or entity.","usage_examples":"Use when vows and their breaking have power."},"ru":{"name":"Нарушенная клятва","description":"Последствие нарушенного обещания, проявляющееся как проклятие или сущность.","usage_examples":"Используйте, когда клятвы и их нарушение имеют силу."},"ua":{"name":"Порушена клятва","description":"Наслідок порушеної обіцянки, що проявляється як прокляття або сутність.","usage_examples":"Використовуйте, коли клятви та їх порушення мають силу."}}', NULL),
('efe61c68-b317-504a-bc8d-51cdb5116bb1', '00000000-0000-0000-0000-000000000001', 'The Price of Power', 'The inevitable cost that comes due when forbidden strength is claimed.', 'story', 'antagonist', 'Play when exploring consequences of ambition.', '{"en":{"name":"The Price of Power","description":"The inevitable cost that comes due when forbidden strength is claimed.","usage_examples":"Play when exploring consequences of ambition."},"ru":{"name":"Цена власти","description":"Неизбежная цена, которая наступает, когда востребована запретная сила.","usage_examples":"Играйте при исследовании последствий амбиций."},"ua":{"name":"Ціна влади","description":"Неминуча ціна, яка настає, коли затребувана заборонена сила.","usage_examples":"Грайте при дослідженні наслідків амбіцій."}}', NULL),
('00b45559-e54a-5d66-817f-8a8904e82e01', '00000000-0000-0000-0000-000000000001', 'The Thing That Should Not Be', 'An abomination that defies natural law and sanity itself.', 'story', 'antagonist', 'Introduce when facing cosmic horror or the unnatural.', '{"en":{"name":"The Thing That Should Not Be","description":"An abomination that defies natural law and sanity itself.","usage_examples":"Introduce when facing cosmic horror or the unnatural."},"ru":{"name":"То, чего не должно быть","description":"Мерзость, бросающая вызов законам природы и самому рассудку.","usage_examples":"Вводите, когда сталкиваетесь с космическим ужасом или неестественным."},"ua":{"name":"Те, чого не повинно бути","description":"Мерзота, що кидає виклик законам природи і самому розуму.","usage_examples":"Вводьте, коли стикаєтеся з космічним жахом або неприродним."}}', NULL)
INSERT INTO "public"."cards" (id, deck_id, name, description, type, category, usage_examples, translations, image_url) VALUES
('e8a68892-75a5-5823-a705-02508644f560', '00000000-0000-0000-0000-000000000001', 'The Haunted Forest', 'Ancient woods where spirits dwell and paths shift beneath unwary feet.', 'story', 'setting', 'Use when characters need to journey through dangerous wilderness.', '{"en":{"name":"The Haunted Forest","description":"Ancient woods where spirits dwell and paths shift beneath unwary feet.","usage_examples":"Use when characters need to journey through dangerous wilderness."},"ru":{"name":"Проклятый лес","description":"Древние леса, где обитают духи, а тропы меняются под ногами неосторожных.","usage_examples":"Используйте, когда персонажам нужно путешествовать через опасную дикую местность."},"ua":{"name":"Проклятий ліс","description":"Стародавні ліси, де мешкають духи, а стежки змінюються під ногами необережних.","usage_examples":"Використовуйте, коли персонажам потрібно подорожувати через небезпечну дику місцевість."}}', NULL),
('26567be1-3af4-5f57-a053-0b93c60c2d2a', '00000000-0000-0000-0000-000000000001', 'The Crumbling Castle', 'A once-grand fortress now falling to ruin, holding secrets in its decay.', 'story', 'setting', 'Play when exploring abandoned places or fallen kingdoms.', '{"en":{"name":"The Crumbling Castle","description":"A once-grand fortress now falling to ruin, holding secrets in its decay.","usage_examples":"Play when exploring abandoned places or fallen kingdoms."},"ru":{"name":"Разрушающийся замок","description":"Некогда величественная крепость, ныне приходящая в упадок, хранящая секреты в своем разрушении.","usage_examples":"Играйте при исследовании заброшенных мест или павших королевств."},"ua":{"name":"Замок, що руйнується","description":"Колись велична фортеця, що нині занепадає, зберігаючи секрети у своєму руйнуванні.","usage_examples":"Грайте при дослідженні покинутих місць або полеглих королівств."}}', NULL),
('4e2d4106-d341-57a0-b54f-e2fda6fc1ba2', '00000000-0000-0000-0000-000000000001', 'The Hidden Village', 'A settlement concealed from the outside world, preserving old ways.', 'story', 'setting', 'Introduce when finding refuge or discovering lost communities.', '{"en":{"name":"The Hidden Village","description":"A settlement concealed from the outside world, preserving old ways.","usage_examples":"Introduce when finding refuge or discovering lost communities."},"ru":{"name":"Скрытая деревня","description":"Поселение, скрытое от внешнего мира, сохраняющее старые обычаи.","usage_examples":"Вводите, когда находите убежище или открываете потерянные сообщества."},"ua":{"name":"Приховане село","description":"Поселення, приховане від зовнішнього світу, що зберігає старі звичаї.","usage_examples":"Вводьте, коли знаходите притулок або відкриваєте втрачені спільноти."}}', NULL),
('c796cde4-0850-5ffe-9471-43021e28ba46', '00000000-0000-0000-0000-000000000001', 'The Tower with No Doors', 'A mysterious spire with no visible entrance, defying those who seek entry.', 'story', 'setting', 'Use when facing impossible architecture or magical barriers.', '{"en":{"name":"The Tower with No Doors","description":"A mysterious spire with no visible entrance, defying those who seek entry.","usage_examples":"Use when facing impossible architecture or magical barriers."},"ru":{"name":"Башня без дверей","description":"Таинственный шпиль без видимого входа, бросающий вызов тем, кто ищет входа.","usage_examples":"Используйте, когда сталкиваетесь с невозможной архитектурой или магическими барьерами."},"ua":{"name":"Вежа без дверей","description":"Таємничий шпиль без видимого входу, що кидає виклик тим, хто шукає входу.","usage_examples":"Використовуйте, коли стикаєтеся з неможливою архітектурою або магічними бар''єрами."}}', NULL),
('0a3c1f6c-d4ae-5216-b3d3-580b527cd05b', '00000000-0000-0000-0000-000000000001', 'The City of Masks', 'An urban center where everyone hides their true face behind elaborate disguises.', 'story', 'setting', 'Play when exploring themes of identity and deception.', '{"en":{"name":"The City of Masks","description":"An urban center where everyone hides their true face behind elaborate disguises.","usage_examples":"Play when exploring themes of identity and deception."},"ru":{"name":"Город масок","description":"Городской центр, где каждый скрывает свое истинное лицо за сложными масками.","usage_examples":"Играйте при исследовании тем идентичности и обмана."},"ua":{"name":"Місто масок","description":"Міський центр, де кожен приховує своє справжнє обличчя за складними масками.","usage_examples":"Грайте при дослідженні тем ідентичності та обману."}}', NULL),
('1ac81614-6821-5326-ab0b-57288591b591', '00000000-0000-0000-0000-000000000001', 'The Frozen Wastes', 'Endless ice and snow where survival itself is a daily battle.', 'story', 'setting', 'Introduce when facing harsh environments and isolation.', '{"en":{"name":"The Frozen Wastes","description":"Endless ice and snow where survival itself is a daily battle.","usage_examples":"Introduce when facing harsh environments and isolation."},"ru":{"name":"Ледяные пустоши","description":"Бесконечный лед и снег, где само выживание — это ежедневная битва.","usage_examples":"Вводите, когда сталкиваетесь с суровыми условиями и изоляцией."},"ua":{"name":"Крижані пустки","description":"Нескінченний лід і сніг, де саме виживання — це щоденна битва.","usage_examples":"Вводьте, коли стикаєтеся з суворими умовами та ізоляцією."}}', NULL),
('9d78e41e-a664-53df-9898-6188aa32e969', '00000000-0000-0000-0000-000000000001', 'The Desert of Whispers', 'Arid lands where the wind carries voices of the lost and forgotten.', 'story', 'setting', 'Use when desolation and mystery combine.', '{"en":{"name":"The Desert of Whispers","description":"Arid lands where the wind carries voices of the lost and forgotten.","usage_examples":"Use when desolation and mystery combine."},"ru":{"name":"Пустыня шепотов","description":"Засушливые земли, где ветер несет голоса потерянных и забытых.","usage_examples":"Используйте, когда запустение и тайна сочетаются."},"ua":{"name":"Пустеля шепотів","description":"Посушливі землі, де вітер несе голоси втрачених і забутих.","usage_examples":"Використовуйте, коли запустіння і таємниця поєднуються."}}', NULL),
('985771cd-9214-51c3-9f7d-31fa6d54252a', '00000000-0000-0000-0000-000000000001', 'The Library of Forgotten Names', 'A vast repository of knowledge where even memories are catalogued and stored.', 'story', 'setting', 'Play when seeking knowledge or exploring the power of memory.', '{"en":{"name":"The Library of Forgotten Names","description":"A vast repository of knowledge where even memories are catalogued and stored.","usage_examples":"Play when seeking knowledge or exploring the power of memory."},"ru":{"name":"Библиотека забытых имен","description":"Огромное хранилище знаний, где даже воспоминания каталогизируются и хранятся.","usage_examples":"Играйте при поиске знаний или исследовании силы памяти."},"ua":{"name":"Бібліотека забутих імен","description":"Величезне сховище знань, де навіть спогади каталогізуються і зберігаються.","usage_examples":"Грайте при пошуку знань або дослідженні сили пам''яті."}}', NULL),
('ade58d5f-ad39-5ee9-8d1b-599199c42c3a', '00000000-0000-0000-0000-000000000001', 'The Bridge Between Worlds', 'A crossing point that connects different realms or realities.', 'story', 'setting', 'Introduce when traveling between planes or dimensions.', '{"en":{"name":"The Bridge Between Worlds","description":"A crossing point that connects different realms or realities.","usage_examples":"Introduce when traveling between planes or dimensions."},"ru":{"name":"Мост между мирами","description":"Точка пересечения, соединяющая разные царства или реальности.","usage_examples":"Вводите при путешествии между планами или измерениями."},"ua":{"name":"Міст між світами","description":"Точка перетину, що з''єднує різні царства або реальності.","usage_examples":"Вводьте при подорожі між планами або вимірами."}}', NULL),
('ad917d95-9c26-5c3b-8c2c-0eb338fafc2c', '00000000-0000-0000-0000-000000000001', 'The Island That Moves', 'A landmass that drifts across the sea, never found in the same place twice.', 'story', 'setting', 'Use when seeking the unfindable or dealing with shifting geography.', '{"en":{"name":"The Island That Moves","description":"A landmass that drifts across the sea, never found in the same place twice.","usage_examples":"Use when seeking the unfindable or dealing with shifting geography."},"ru":{"name":"Остров, который движется","description":"Участок суши, дрейфующий по морю, никогда не находящийся в одном и том же месте дважды.","usage_examples":"Используйте при поиске неуловимого или столкновении с меняющейся географией."},"ua":{"name":"Острів, що рухається","description":"Ділянка суші, що дрейфує по морю, ніколи не знаходиться в одному і тому ж місці двічі.","usage_examples":"Використовуйте при пошуку невловимого або зіткненні зі змінною географією."}}', NULL),
('6cd6c1d9-c797-58ea-aacc-2819410e9d5d', '00000000-0000-0000-0000-000000000001', 'The Market of Lost Things', 'A bazaar where items thought gone forever can be found and purchased.', 'story', 'setting', 'Play when seeking specific objects or making deals.', '{"en":{"name":"The Market of Lost Things","description":"A bazaar where items thought gone forever can be found and purchased.","usage_examples":"Play when seeking specific objects or making deals."},"ru":{"name":"Рынок потерянных вещей","description":"Базар, где вещи, считавшиеся исчезнувшими навсегда, могут быть найдены и куплены.","usage_examples":"Играйте при поиске конкретных предметов или заключении сделок."},"ua":{"name":"Ринок загублених речей","description":"Базар, де речі, що вважалися зниклими назавжди, можуть бути знайдені і куплені.","usage_examples":"Грайте при пошуку конкретних предметів або укладанні угод."}}', NULL),
('d451d70c-9f0b-5517-90b3-d3ecde07f5e6', '00000000-0000-0000-0000-000000000001', 'The Sunken Temple', 'A place of worship now beneath the waves, still holding ancient power.', 'story', 'setting', 'Introduce when exploring underwater or reclaiming the past.', '{"en":{"name":"The Sunken Temple","description":"A place of worship now beneath the waves, still holding ancient power.","usage_examples":"Introduce when exploring underwater or reclaiming the past."},"ru":{"name":"Затонувший храм","description":"Место поклонения, ныне находящееся под волнами, все еще хранящее древнюю силу.","usage_examples":"Вводите при исследовании подводного мира или возвращении прошлого."},"ua":{"name":"Затонулий храм","description":"Місце поклоніння, що нині знаходиться під хвилями, все ще зберігає стародавню силу.","usage_examples":"Вводьте при дослідженні підводного світу або поверненні минулого."}}', NULL),
('d5cd227a-1bfc-5060-bac8-07f501195f7a', '00000000-0000-0000-0000-000000000001', 'The Skyborne Citadel', 'A fortress floating among the clouds, accessible only by flight or magic.', 'story', 'setting', 'Use when reaching for the heavens or facing aerial challenges.', '{"en":{"name":"The Skyborne Citadel","description":"A fortress floating among the clouds, accessible only by flight or magic.","usage_examples":"Use when reaching for the heavens or facing aerial challenges."},"ru":{"name":"Небесная цитадель","description":"Крепость, парящая среди облаков, доступная только полетом или магией.","usage_examples":"Используйте, когда тянетесь к небесам или сталкиваетесь с воздушными испытаниями."},"ua":{"name":"Небесна цитадель","description":"Фортеця, що ширяє серед хмар, доступна тільки польотом або магією.","usage_examples":"Використовуйте, коли тягнетеся до небес або стикаєтеся з повітряними випробуваннями."}}', NULL),
('959951bc-6a6e-5b3d-a527-16a11531b9cb', '00000000-0000-0000-0000-000000000001', 'The Endless Staircase', 'Steps that climb forever upward or descend into infinite depths.', 'story', 'setting', 'Play when facing impossible journeys or testing endurance.', '{"en":{"name":"The Endless Staircase","description":"Steps that climb forever upward or descend into infinite depths.","usage_examples":"Play when facing impossible journeys or testing endurance."},"ru":{"name":"Бесконечная лестница","description":"Ступени, ведущие вечно вверх или спускающиеся в бесконечные глубины.","usage_examples":"Играйте, когда сталкиваетесь с невозможными путешествиями или проверкой выносливости."},"ua":{"name":"Нескінченні сходи","description":"Сходи, що ведуть вічно вгору або спускаються в нескінченні глибини.","usage_examples":"Грайте, коли стикаєтеся з неможливими подорожами або перевіркою витривалості."}}', NULL),
('b79f1377-1347-54eb-a535-3b62de97d9c1', '00000000-0000-0000-0000-000000000001', 'The Garden of Bones', 'A grotesque paradise where death blooms into strange beauty.', 'story', 'setting', 'Introduce when exploring the boundary between life and death.', '{"en":{"name":"The Garden of Bones","description":"A grotesque paradise where death blooms into strange beauty.","usage_examples":"Introduce when exploring the boundary between life and death."},"ru":{"name":"Сад костей","description":"Гротескный рай, где смерть расцветает в странную красоту.","usage_examples":"Вводите при исследовании границы между жизнью и смертью."},"ua":{"name":"Сад кісток","description":"Гротескний рай, де смерть розквітає в дивну красу.","usage_examples":"Вводьте при дослідженні кордону між життям і смертю."}}', NULL),
('01586760-f75b-5f66-a1e9-c6e5b707389b', '00000000-0000-0000-0000-000000000001', 'The Hollow Mountain', 'A peak with vast caverns inside, home to ancient civilizations or creatures.', 'story', 'setting', 'Use when delving underground or discovering hidden worlds.', '{"en":{"name":"The Hollow Mountain","description":"A peak with vast caverns inside, home to ancient civilizations or creatures.","usage_examples":"Use when delving underground or discovering hidden worlds."},"ru":{"name":"Полая гора","description":"Пик с огромными пещерами внутри, дом для древних цивилизаций или существ.","usage_examples":"Используйте при погружении под землю или открытии скрытых миров."},"ua":{"name":"Порожня гора","description":"Пік з величезними печерами всередині, дім для стародавніх цивілізацій або істот.","usage_examples":"Використовуйте при зануренні під землю або відкритті прихованих світів."}}', NULL),
('9574bd92-b912-5770-b789-f8aef7669e95', '00000000-0000-0000-0000-000000000001', 'The Mirror Lake', 'Waters so still they reflect not just images but truths and futures.', 'story', 'setting', 'Play when seeking visions or confronting reflections.', '{"en":{"name":"The Mirror Lake","description":"Waters so still they reflect not just images but truths and futures.","usage_examples":"Play when seeking visions or confronting reflections."},"ru":{"name":"Зеркальное озеро","description":"Воды настолько спокойные, что отражают не только образы, но и истины и будущее.","usage_examples":"Играйте при поиске видений или столкновении с отражениями."},"ua":{"name":"Дзеркальне озеро","description":"Води настільки спокійні, що відображають не тільки образи, а й істини і майбутнє.","usage_examples":"Грайте при пошуку видінь або зіткненні з відображеннями."}}', NULL),
('73b7600d-c765-570d-9969-0033b88c9b2b', '00000000-0000-0000-0000-000000000001', 'The Labyrinth Below', 'Twisting passages beneath the earth where getting lost is inevitable.', 'story', 'setting', 'Introduce when facing confusion and the need to find a path.', '{"en":{"name":"The Labyrinth Below","description":"Twisting passages beneath the earth where getting lost is inevitable.","usage_examples":"Introduce when facing confusion and the need to find a path."},"ru":{"name":"Лабиринт внизу","description":"Извилистые проходы под землей, где заблудиться неизбежно.","usage_examples":"Вводите, когда сталкиваетесь с путаницей и необходимостью найти путь."},"ua":{"name":"Лабіринт внизу","description":"Звивисті проходи під землею, де заблукати неминуче.","usage_examples":"Вводьте, коли стикаєтеся з плутаниною і необхідністю знайти шлях."}}', NULL),
('2a9bba94-ed96-579c-821c-408f2968ebb6', '00000000-0000-0000-0000-000000000001', 'The Clockwork City', 'A metropolis of gears and steam where everything runs with mechanical precision.', 'story', 'setting', 'Use when exploring themes of order, industry, and automation.', '{"en":{"name":"The Clockwork City","description":"A metropolis of gears and steam where everything runs with mechanical precision.","usage_examples":"Use when exploring themes of order, industry, and automation."},"ru":{"name":"Заводной город","description":"Мегаполис шестеренок и пара, где все работает с механической точностью.","usage_examples":"Используйте при исследовании тем порядка, промышленности и автоматизации."},"ua":{"name":"Заводне місто","description":"Мегаполіс шестерень і пари, де все працює з механічною точністю.","usage_examples":"Використовуйте при дослідженні тем порядку, промисловості та автоматизації."}}', NULL),
('998f25a4-6473-5a4b-a7dd-599a221142a4', '00000000-0000-0000-0000-000000000001', 'The Battlefield of Ghosts', 'A site of ancient war where the dead still fight their eternal conflict.', 'story', 'setting', 'Play when the past refuses to stay buried.', '{"en":{"name":"The Battlefield of Ghosts","description":"A site of ancient war where the dead still fight their eternal conflict.","usage_examples":"Play when the past refuses to stay buried."},"ru":{"name":"Поле битвы призраков","description":"Место древней войны, где мертвые все еще ведут свой вечный конфликт.","usage_examples":"Играйте, когда прошлое отказывается оставаться похороненным."},"ua":{"name":"Поле битви привидів","description":"Місце стародавньої війни, де мертві все ще ведуть свій вічний конфлікт.","usage_examples":"Грайте, коли минуле відмовляється залишатися похованим."}}', NULL),
('54754e4d-bfd9-5bd9-bd91-8ed73de069ec', '00000000-0000-0000-0000-000000000001', 'The River of Time', 'A waterway that flows through different eras, allowing travel through history.', 'story', 'setting', 'Introduce when time travel or temporal themes are important.', '{"en":{"name":"The River of Time","description":"A waterway that flows through different eras, allowing travel through history.","usage_examples":"Introduce when time travel or temporal themes are important."},"ru":{"name":"Река времени","description":"Водный путь, текущий через разные эпохи, позволяющий путешествовать сквозь историю.","usage_examples":"Вводите, когда путешествия во времени или временные темы важны."},"ua":{"name":"Річка часу","description":"Водний шлях, що тече через різні епохи, дозволяючи подорожувати крізь історію.","usage_examples":"Вводьте, коли подорожі в часі або часові теми важливі."}}', NULL),
('e50b93e8-8a24-547d-b8d2-ce2036034eb2', '00000000-0000-0000-0000-000000000001', 'The Forbidden Archives', 'A collection of knowledge deemed too dangerous for common access.', 'story', 'setting', 'Use when seeking forbidden lore or facing censorship.', '{"en":{"name":"The Forbidden Archives","description":"A collection of knowledge deemed too dangerous for common access.","usage_examples":"Use when seeking forbidden lore or facing censorship."},"ru":{"name":"Запретные архивы","description":"Коллекция знаний, считающихся слишком опасными для общего доступа.","usage_examples":"Используйте при поиске запретных знаний или столкновении с цензурой."},"ua":{"name":"Заборонені архіви","description":"Колекція знань, що вважаються занадто небезпечними для загального доступу.","usage_examples":"Використовуйте при пошуку заборонених знань або зіткненні з цензурою."}}', NULL),
('701f41c4-636a-59d3-88f5-24512f882d2d', '00000000-0000-0000-0000-000000000001', 'The Ship of the Dead', 'A vessel crewed by spirits, sailing between the living world and the afterlife.', 'story', 'setting', 'Play when dealing with death, passage, and the supernatural.', '{"en":{"name":"The Ship of the Dead","description":"A vessel crewed by spirits, sailing between the living world and the afterlife.","usage_examples":"Play when dealing with death, passage, and the supernatural."},"ru":{"name":"Корабль мертвых","description":"Судно, укомплектованное духами, плавающее между миром живых и загробным миром.","usage_examples":"Играйте, когда имеете дело со смертью, переходом и сверхъестественным."},"ua":{"name":"Корабель мертвих","description":"Судно, укомплектоване духами, що плаває між світом живих і потойбічним світом.","usage_examples":"Грайте, коли маєте справу зі смертю, переходом і надприродним."}}', NULL),
('8e28bfa2-38d5-53ae-8462-749a5b78f86a', '00000000-0000-0000-0000-000000000001', 'The Dreaming Spire', 'A tower where reality and dreams merge, making the impossible possible.', 'story', 'setting', 'Introduce when dreams become real or reality becomes fluid.', '{"en":{"name":"The Dreaming Spire","description":"A tower where reality and dreams merge, making the impossible possible.","usage_examples":"Introduce when dreams become real or reality becomes fluid."},"ru":{"name":"Шпиль сновидений","description":"Башня, где реальность и сны сливаются, делая невозможное возможным.","usage_examples":"Вводите, когда сны становятся реальными или реальность становится текучей."},"ua":{"name":"Шпиль сновидінь","description":"Вежа, де реальність і сни зливаються, роблячи неможливе можливим.","usage_examples":"Вводьте, коли сни стають реальними або реальність стає плинною."}}', NULL),
('e0a5211e-6780-5e31-84b5-a5b5588e8277', '00000000-0000-0000-0000-000000000001', 'The Crater of Stars', 'A massive impact site where fragments of the heavens fell to earth.', 'story', 'setting', 'Use when dealing with cosmic events or celestial power.', '{"en":{"name":"The Crater of Stars","description":"A massive impact site where fragments of the heavens fell to earth.","usage_examples":"Use when dealing with cosmic events or celestial power."},"ru":{"name":"Кратер звезд","description":"Место массивного удара, где фрагменты небес упали на землю.","usage_examples":"Используйте, когда имеете дело с космическими событиями или небесной силой."},"ua":{"name":"Кратер зірок","description":"Місце масивного удару, де фрагменти небес впали на землю.","usage_examples":"Використовуйте, коли маєте справу з космічними подіями або небесною силою."}}', NULL),
('fe8bff79-ad3f-59f4-bc92-495491b583d5', '00000000-0000-0000-0000-000000000001', 'The Edge of the World', 'The boundary where known lands end and the unknown begins.', 'story', 'setting', 'Play when exploring the limits of the world or venturing into the void.', '{"en":{"name":"The Edge of the World","description":"The boundary where known lands end and the unknown begins.","usage_examples":"Play when exploring the limits of the world or venturing into the void."},"ru":{"name":"Край света","description":"Граница, где заканчиваются известные земли и начинается неизвестное.","usage_examples":"Играйте при исследовании пределов мира или путешествии в пустоту."},"ua":{"name":"Край світу","description":"Кордон, де закінчуються відомі землі і починається невідоме.","usage_examples":"Грайте при дослідженні меж світу або подорожі в порожнечу."}}', NULL),
('9ddad146-229f-5c2b-84f2-d0d19c5d8b86', '00000000-0000-0000-0000-000000000001', 'The Moonlit Carnival', 'A traveling fair that appears only under the full moon, offering wonders and dangers.', 'story', 'setting', 'Introduce when magic and entertainment combine.', '{"en":{"name":"The Moonlit Carnival","description":"A traveling fair that appears only under the full moon, offering wonders and dangers.","usage_examples":"Introduce when magic and entertainment combine."},"ru":{"name":"Лунный карнавал","description":"Бродячая ярмарка, появляющаяся только при полной луне, предлагающая чудеса и опасности.","usage_examples":"Вводите, когда магия и развлечения сочетаются."},"ua":{"name":"Місячний карнавал","description":"Бродячий ярмарок, що з''являється тільки при повному місяці, пропонуючи чудеса і небезпеки.","usage_examples":"Вводьте, коли магія і розваги поєднуються."}}', NULL),
('b970c3a7-932d-5bbc-84fe-a58fb58c2ab1', '00000000-0000-0000-0000-000000000001', 'The Buried Cathedral', 'A holy place swallowed by earth or sand, still resonating with sacred power.', 'story', 'setting', 'Use when uncovering lost faith or exploring buried history.', '{"en":{"name":"The Buried Cathedral","description":"A holy place swallowed by earth or sand, still resonating with sacred power.","usage_examples":"Use when uncovering lost faith or exploring buried history."},"ru":{"name":"Погребенный собор","description":"Святое место, поглощенное землей или песком, все еще резонирующее священной силой.","usage_examples":"Используйте при открытии утраченной веры или исследовании погребенной истории."},"ua":{"name":"Похований собор","description":"Святе місце, поглинене землею або піском, все ще резонує священною силою.","usage_examples":"Використовуйте при відкритті втраченої віри або дослідженні похованої історії."}}', NULL),
('6655b19e-0054-53cc-8592-8dd144523203', '00000000-0000-0000-0000-000000000001', 'The Realm of Echoes', 'A place where every sound, word, and action repeats endlessly.', 'story', 'setting', 'Play when dealing with consequences or the weight of the past.', '{"en":{"name":"The Realm of Echoes","description":"A place where every sound, word, and action repeats endlessly.","usage_examples":"Play when dealing with consequences or the weight of the past."},"ru":{"name":"Царство эха","description":"Место, где каждый звук, слово и действие повторяются бесконечно.","usage_examples":"Играйте, когда имеете дело с последствиями или тяжестью прошлого."},"ua":{"name":"Царство відлуння","description":"Місце, де кожен звук, слово і дія повторюються нескінченно.","usage_examples":"Грайте, коли маєте справу з наслідками або вагою минулого."}}', NULL),
('87e69745-af31-5410-93bd-36864ac5c88c', '00000000-0000-0000-0000-000000000001', 'The Last Safe Place', 'A final refuge in a world falling to darkness or chaos.', 'story', 'setting', 'Introduce when hope is scarce and sanctuary is precious.', '{"en":{"name":"The Last Safe Place","description":"A final refuge in a world falling to darkness or chaos.","usage_examples":"Introduce when hope is scarce and sanctuary is precious."},"ru":{"name":"Последнее безопасное место","description":"Последнее убежище в мире, погружающемся во тьму или хаос.","usage_examples":"Вводите, когда надежды мало, а убежище драгоценно."},"ua":{"name":"Останнє безпечне місце","description":"Останній притулок у світі, що занурюється в темряву або хаос.","usage_examples":"Вводьте, коли надії мало, а притулок дорогоцінний."}}', NULL)
INSERT INTO "public"."cards" (id, deck_id, name, description, type, category, usage_examples, translations, image_url) VALUES
('d3372854-ae27-5865-bd88-0d13ca96821b', '00000000-0000-0000-0000-000000000001', 'The Sword of Truth', 'A blade that cuts through lies and reveals what is hidden.', 'story', 'object', 'Use when truth must be revealed or deception must be cut away.', '{"en":{"name":"The Sword of Truth","description":"A blade that cuts through lies and reveals what is hidden.","usage_examples":"Use when truth must be revealed or deception must be cut away."},"ru":{"name":"Меч Истины","description":"Клинок, рассекающий ложь и открывающий скрытое.","usage_examples":"Используйте, когда правда должна быть раскрыта или обман должен быть отсечен."},"ua":{"name":"Меч Істини","description":"Лезо, що розсікає брехню і розкриває приховане.","usage_examples":"Використовуйте, коли правда повинна бути розкрита або обман повинен бути відсічений."}}', NULL),
('226b6fc1-3571-544c-9a15-e5553d2a664a', '00000000-0000-0000-0000-000000000001', 'The Crown of Lies', 'A royal circlet that grants power through deception and illusion.', 'story', 'object', 'Play when exploring corruption of power or the price of rule.', '{"en":{"name":"The Crown of Lies","description":"A royal circlet that grants power through deception and illusion.","usage_examples":"Play when exploring corruption of power or the price of rule."},"ru":{"name":"Корона Лжи","description":"Королевский обруч, дарующий власть через обман и иллюзии.","usage_examples":"Играйте при исследовании коррупции власти или цены правления."},"ua":{"name":"Корона Брехні","description":"Королівський обруч, що дарує владу через обман та ілюзії.","usage_examples":"Грайте при дослідженні корупції влади або ціни правління."}}', NULL),
('735e1ef7-4ffc-5565-a6cf-0206f63845de', '00000000-0000-0000-0000-000000000001', 'The Map of Destiny', 'A chart that shows not where you are, but where you are meant to be.', 'story', 'object', 'Introduce when fate and free will collide.', '{"en":{"name":"The Map of Destiny","description":"A chart that shows not where you are, but where you are meant to be.","usage_examples":"Introduce when fate and free will collide."},"ru":{"name":"Карта Судьбы","description":"Карта, показывающая не где вы находитесь, а где вам суждено быть.","usage_examples":"Вводите, когда судьба и свобода воли сталкиваются."},"ua":{"name":"Карта Долі","description":"Карта, що показує не де ви знаходитесь, а де вам судилося бути.","usage_examples":"Вводьте, коли доля і свобода волі стикаються."}}', NULL),
('eaaff672-f693-5a79-9d3a-30112414bcbd', '00000000-0000-0000-0000-000000000001', 'The Elixir of Memory', 'A potion that can restore lost memories or erase unwanted ones.', 'story', 'object', 'Use when the past must be remembered or forgotten.', '{"en":{"name":"The Elixir of Memory","description":"A potion that can restore lost memories or erase unwanted ones.","usage_examples":"Use when the past must be remembered or forgotten."},"ru":{"name":"Эликсир Памяти","description":"Зелье, способное восстановить потерянные воспоминания или стереть нежелательные.","usage_examples":"Используйте, когда прошлое нужно вспомнить или забыть."},"ua":{"name":"Еліксир Пам''яті","description":"Зілля, здатне відновити втрачені спогади або стерти небажані.","usage_examples":"Використовуйте, коли минуле потрібно згадати або забути."}}', NULL),
('7a17108d-2ac6-53d7-8365-309379d3f04a', '00000000-0000-0000-0000-000000000001', 'The Ring of Binding', 'A band that creates unbreakable connections or imprisons the wearer.', 'story', 'object', 'Play when bonds or imprisonment are themes.', '{"en":{"name":"The Ring of Binding","description":"A band that creates unbreakable connections or imprisons the wearer.","usage_examples":"Play when bonds or imprisonment are themes."},"ru":{"name":"Кольцо Связывания","description":"Кольцо, создающее неразрывные связи или заточающее владельца.","usage_examples":"Играйте, когда узы или заточение являются темами."},"ua":{"name":"Перстень Зв''язування","description":"Перстень, що створює нерозривні зв''язки або ув''язнює власника. ","usage_examples":"Грайте, коли узи або ув''язнення є темами."}}', NULL),
('bf3cf21a-f77d-5e4e-8b6d-7a561c43dfb6', '00000000-0000-0000-0000-000000000001', 'The Lantern of Lost Souls', 'A light that guides the dead or reveals spirits to the living.', 'story', 'object', 'Introduce when dealing with ghosts or the afterlife.', '{"en":{"name":"The Lantern of Lost Souls","description":"A light that guides the dead or reveals spirits to the living.","usage_examples":"Introduce when dealing with ghosts or the afterlife."},"ru":{"name":"Фонарь Потерянных Душ","description":"Свет, направляющий мертвых или открывающий духов живым.","usage_examples":"Вводите, когда имеете дело с призраками или загробной жизнью."},"ua":{"name":"Ліхтар Втрачених Душ","description":"Світло, що направляє мертвих або відкриває духів живим.","usage_examples":"Вводьте, коли маєте справу з привидами або потойбічним життям."}}', NULL),
('bd01c606-b1ee-50da-93c8-d3d6ccdb484c', '00000000-0000-0000-0000-000000000001', 'The Book That Writes Itself', 'A tome that records events as they happen or predicts what will come.', 'story', 'object', 'Use when prophecy or documentation is important.', '{"en":{"name":"The Book That Writes Itself","description":"A tome that records events as they happen or predicts what will come.","usage_examples":"Use when prophecy or documentation is important."},"ru":{"name":"Книга, Которая Пишет Сама Себя","description":"Том, записывающий события по мере того, как они происходят, или предсказывающий грядущее.","usage_examples":"Используйте, когда пророчество или документация важны."},"ua":{"name":"Книга, Що Пише Сама Себе","description":"Том, що записує події в міру того, як вони відбуваються, або пророкує майбутнє.","usage_examples":"Використовуйте, коли пророцтво або документація важливі."}}', NULL),
('052c2a2a-43ca-5757-96b2-2d6914ffbc1a', '00000000-0000-0000-0000-000000000001', 'The Mirror of Regret', 'A looking glass that shows not your reflection but your greatest mistakes.', 'story', 'object', 'Play when confronting the past or seeking redemption.', '{"en":{"name":"The Mirror of Regret","description":"A looking glass that shows not your reflection but your greatest mistakes.","usage_examples":"Play when confronting the past or seeking redemption."},"ru":{"name":"Зеркало Сожаления","description":"Зеркало, показывающее не ваше отражение, а ваши величайшие ошибки.","usage_examples":"Играйте при столкновении с прошлым или поиске искупления."},"ua":{"name":"Дзеркало Жалю","description":"Дзеркало, що показує не ваше відображення, а ваші найбільші помилки.","usage_examples":"Грайте при зіткненні з минулим або пошуку спокути."}}', NULL),
('700f29e5-9b0e-5dbf-bac2-b4c1e339d8e0', '00000000-0000-0000-0000-000000000001', 'The Key to the End', 'An implement that can unlock any door, including the final one.', 'story', 'object', 'Introduce when access or endings are at stake.', '{"en":{"name":"The Key to the End","description":"An implement that can unlock any door, including the final one.","usage_examples":"Introduce when access or endings are at stake."},"ru":{"name":"Ключ к Концу","description":"Инструмент, способный открыть любую дверь, включая последнюю.","usage_examples":"Вводите, когда доступ или концовки на кону."},"ua":{"name":"Ключ до Кінця","description":"Інструмент, здатний відкрити будь-які двері, включаючи останні.","usage_examples":"Вводьте, коли доступ або кінцівки на кону."}}', NULL),
('d2dc8376-a76f-5dd9-8c8b-13265acc5208', '00000000-0000-0000-0000-000000000001', 'The Cloak of Shadows', 'A garment that grants invisibility and passage through darkness.', 'story', 'object', 'Use when stealth or concealment is needed.', '{"en":{"name":"The Cloak of Shadows","description":"A garment that grants invisibility and passage through darkness.","usage_examples":"Use when stealth or concealment is needed."},"ru":{"name":"Плащ Теней","description":"Одежда, дарующая невидимость и проход сквозь тьму.","usage_examples":"Используйте, когда нужны скрытность или маскировка."},"ua":{"name":"Плащ Тіней","description":"Одяг, що дарує невидимість і прохід крізь темряву.","usage_examples":"Використовуйте, коли потрібні скритність або маскування."}}', NULL),
('cc7d26f0-25d8-5b88-972a-e0b9bb2f9288', '00000000-0000-0000-0000-000000000001', 'The Coin That Decides Fate', 'A piece of currency that, when flipped, determines destiny itself.', 'story', 'object', 'Play when chance and fate must be tested.', '{"en":{"name":"The Coin That Decides Fate","description":"A piece of currency that, when flipped, determines destiny itself.","usage_examples":"Play when chance and fate must be tested."},"ru":{"name":"Монета, Решающая Судьбу","description":"Монета, которая при подбрасывании определяет саму судьбу.","usage_examples":"Играйте, когда шанс и судьба должны быть испытаны."},"ua":{"name":"Монета, Що Вирішує Долю","description":"Монета, яка при підкиданні визначає саму долю.","usage_examples":"Грайте, коли шанс і доля повинні бути випробувані."}}', NULL),
('4fcb174f-6785-508e-9eef-5c1ed36694e3', '00000000-0000-0000-0000-000000000001', 'The Bone Flute', 'An instrument carved from remains that plays songs of death and sorrow.', 'story', 'object', 'Introduce when music has dark power.', '{"en":{"name":"The Bone Flute","description":"An instrument carved from remains that plays songs of death and sorrow.","usage_examples":"Introduce when music has dark power."},"ru":{"name":"Костяная Флейта","description":"Инструмент, вырезанный из останков, играющий песни смерти и печали.","usage_examples":"Вводите, когда музыка имеет темную силу."},"ua":{"name":"Кістяна Флейта","description":"Інструмент, вирізаний з останків, що грає пісні смерті і печалі.","usage_examples":"Вводьте, коли музика має темну силу."}}', NULL),
('03448b40-76f2-58a9-b8a1-52235a1a2142', '00000000-0000-0000-0000-000000000001', 'The Phoenix Feather', 'A plume from the immortal bird, granting rebirth or resurrection.', 'story', 'object', 'Use when death can be overcome or renewal is possible.', '{"en":{"name":"The Phoenix Feather","description":"A plume from the immortal bird, granting rebirth or resurrection.","usage_examples":"Use when death can be overcome or renewal is possible."},"ru":{"name":"Перо Феникса","description":"Перо бессмертной птицы, дарующее возрождение или воскрешение.","usage_examples":"Используйте, когда смерть может быть преодолена или возможно обновление."},"ua":{"name":"Перо Фенікса","description":"Перо безсмертного птаха, що дарує відродження або воскресіння.","usage_examples":"Використовуйте, коли смерть може бути подолана або можливе оновлення."}}', NULL),
('66459742-fae1-54c7-a6ad-5bf7a88014ca', '00000000-0000-0000-0000-000000000001', 'The Hourglass of Undoing', 'A timepiece that can reverse moments or extend them indefinitely.', 'story', 'object', 'Play when time manipulation is needed.', '{"en":{"name":"The Hourglass of Undoing","description":"A timepiece that can reverse moments or extend them indefinitely.","usage_examples":"Play when time manipulation is needed."},"ru":{"name":"Песочные Часы Отмены","description":"Часы, способные обращать моменты вспять или продлевать их бесконечно.","usage_examples":"Играйте, когда нужна манипуляция временем."},"ua":{"name":"Пісочний Годинник Скасування","description":"Годинник, здатний звертати моменти назад або продовжувати їх нескінченно.","usage_examples":"Грайте, коли потрібна маніпуляція часом."}}', NULL),
('1f8ccb7d-55ab-5e63-9d2a-d3a8252f4557', '00000000-0000-0000-0000-000000000001', 'The Mask of Many Faces', 'A disguise that allows the wearer to become anyone they choose.', 'story', 'object', 'Introduce when identity is fluid or deception is key.', '{"en":{"name":"The Mask of Many Faces","description":"A disguise that allows the wearer to become anyone they choose.","usage_examples":"Introduce when identity is fluid or deception is key."},"ru":{"name":"Маска Многих Лиц","description":"Маскировка, позволяющая носящему стать кем угодно по своему выбору.","usage_examples":"Вводите, когда идентичность текуча или обман является ключевым."},"ua":{"name":"Маска Багатьох Облич","description":"Маскування, що дозволяє носію стати ким завгодно за своїм вибором.","usage_examples":"Вводьте, коли ідентичність плинна або обман є ключовим."}}', NULL),
('de321597-003f-5c70-86c4-aac2cb86cf3c', '00000000-0000-0000-0000-000000000001', 'The Compass That Points to Danger', 'A navigation tool that always indicates the nearest threat.', 'story', 'object', 'Use when seeking trouble or avoiding it.', '{"en":{"name":"The Compass That Points to Danger","description":"A navigation tool that always indicates the nearest threat.","usage_examples":"Use when seeking trouble or avoiding it."},"ru":{"name":"Компас, Указывающий на Опасность","description":"Навигационный инструмент, всегда указывающий на ближайшую угрозу.","usage_examples":"Используйте при поиске неприятностей или их избегании."},"ua":{"name":"Компас, Що Вказує на Небезпеку","description":"Навігаційний інструмент, що завжди вказує на найближчу загрозу.","usage_examples":"Використовуйте при пошуку неприємностей або їх уникненні."}}', NULL),
('ad2f27a9-cf60-5d31-be57-d5d1008766df', '00000000-0000-0000-0000-000000000001', 'The Seed of the World Tree', 'A kernel containing the potential for infinite growth and life.', 'story', 'object', 'Play when creation or renewal is the theme.', '{"en":{"name":"The Seed of the World Tree","description":"A kernel containing the potential for infinite growth and life.","usage_examples":"Play when creation or renewal is the theme."},"ru":{"name":"Семя Мирового Древа","description":"Зерно, содержащее потенциал для бесконечного роста и жизни.","usage_examples":"Играйте, когда созидание или обновление являются темой."},"ua":{"name":"Насіння Світового Дерева","description":"Зерно, що містить потенціал для нескінченного росту і життя.","usage_examples":"Грайте, коли творення або оновлення є темою."}}', NULL),
('46392a51-1c44-5c29-9eaa-3fd43751d962', '00000000-0000-0000-0000-000000000001', 'The Chain of Promises', 'Links forged from vows that bind those who swear upon them.', 'story', 'object', 'Introduce when oaths and their keeping matter.', '{"en":{"name":"The Chain of Promises","description":"Links forged from vows that bind those who swear upon them.","usage_examples":"Introduce when oaths and their keeping matter."},"ru":{"name":"Цепь Обещаний","description":"Звенья, выкованные из клятв, связывающие тех, кто на них клянется.","usage_examples":"Вводите, когда клятвы и их соблюдение имеют значение."},"ua":{"name":"Ланцюг Обіцянок","description":"Ланки, викувані з клятв, що пов''язують тих, хто на них клянеться.","usage_examples":"Вводьте, коли клятви та їх дотримання мають значення."}}', NULL),
('eb81ea1a-4f67-532b-b94b-61d657b77424', '00000000-0000-0000-0000-000000000001', 'The Gem of Nightfall', 'A jewel that brings darkness wherever it goes.', 'story', 'object', 'Use when shadow and night are needed.', '{"en":{"name":"The Gem of Nightfall","description":"A jewel that brings darkness wherever it goes.","usage_examples":"Use when shadow and night are needed."},"ru":{"name":"Самоцвет Сумерек","description":"Драгоценный камень, приносящий тьму, куда бы он ни попал.","usage_examples":"Используйте, когда нужны тень и ночь."},"ua":{"name":"Самоцвіт Сутінків","description":"Дорогоцінний камінь, що приносить темряву, куди б він не потрапив.","usage_examples":"Використовуйте, коли потрібні тінь і ніч."}}', NULL),
('f95362b0-b5db-52a0-a6e2-63ff317453f8', '00000000-0000-0000-0000-000000000001', 'The Blade That Hungers', 'A weapon with a will of its own, demanding blood and battle.', 'story', 'object', 'Play when weapons have dangerous sentience.', '{"en":{"name":"The Blade That Hungers","description":"A weapon with a will of its own, demanding blood and battle.","usage_examples":"Play when weapons have dangerous sentience."},"ru":{"name":"Клинок, Который Жаждет","description":"Оружие с собственной волей, требующее крови и битвы.","usage_examples":"Играйте, когда оружие обладает опасным разумом."},"ua":{"name":"Лезо, Що Жадає","description":"Зброя з власною волею, що вимагає крові і битви.","usage_examples":"Грайте, коли зброя має небезпечний розум."}}', NULL),
('364335a8-29f2-5d20-95da-fa32c79dc578', '00000000-0000-0000-0000-000000000001', 'The Scroll of Names', 'A document listing all who live, and when crossed out, they die.', 'story', 'object', 'Introduce when names have power over life and death.', '{"en":{"name":"The Scroll of Names","description":"A document listing all who live, and when crossed out, they die.","usage_examples":"Introduce when names have power over life and death."},"ru":{"name":"Свиток Имен","description":"Документ, перечисляющий всех живущих; если имя вычеркнуть, человек умирает.","usage_examples":"Вводите, когда имена имеют власть над жизнью и смертью."},"ua":{"name":"Сувій Імен","description":"Документ, що перераховує всіх живих; якщо ім''я викреслити, людина помирає. ","usage_examples":"Вводьте, коли імена мають владу над життям і смертю."}}', NULL),
('a2a2f5e6-aa9c-5175-a531-1280ca7688f5', '00000000-0000-0000-0000-000000000001', 'The Crown of Thorns', 'A painful symbol of martyrdom that grants power through suffering.', 'story', 'object', 'Use when sacrifice and pain lead to strength.', '{"en":{"name":"The Crown of Thorns","description":"A painful symbol of martyrdom that grants power through suffering.","usage_examples":"Use when sacrifice and pain lead to strength."},"ru":{"name":"Терновый Венец","description":"Болезненный символ мученичества, дарующий силу через страдание.","usage_examples":"Используйте, когда жертва и боль ведут к силе."},"ua":{"name":"Терновий Вінець","description":"Болісний символ мучеництва, що дарує силу через страждання.","usage_examples":"Використовуйте, коли жертва і біль ведуть до сили."}}', NULL),
('35c2aad9-581c-5c8a-ba57-ff8d828213e8', '00000000-0000-0000-0000-000000000001', 'The Bell of Awakening', 'A chime that rouses the sleeping, whether from slumber or death.', 'story', 'object', 'Play when awakening or resurrection is needed.', '{"en":{"name":"The Bell of Awakening","description":"A chime that rouses the sleeping, whether from slumber or death.","usage_examples":"Play when awakening or resurrection is needed."},"ru":{"name":"Колокол Пробуждения","description":"Звон, пробуждающий спящих, будь то ото сна или от смерти.","usage_examples":"Играйте, когда нужно пробуждение или воскрешение."},"ua":{"name":"Дзвін Пробудження","description":"Дзвін, що пробуджує сплячих, будь то від сну або від смерті.","usage_examples":"Грайте, коли потрібне пробудження або воскресіння."}}', NULL),
('757b3ae5-7264-5ba5-b779-8e921af51573', '00000000-0000-0000-0000-000000000001', 'The Lantern That Burns Cold', 'A light that freezes rather than warms, illuminating with ice.', 'story', 'object', 'Introduce when cold and preservation are themes.', '{"en":{"name":"The Lantern That Burns Cold","description":"A light that freezes rather than warms, illuminating with ice.","usage_examples":"Introduce when cold and preservation are themes."},"ru":{"name":"Фонарь, Горящий Холодом","description":"Свет, который замораживает, а не греет, освещая льдом.","usage_examples":"Вводите, когда холод и сохранение являются темами."},"ua":{"name":"Ліхтар, Що Горить Холодом","description":"Світло, яке заморожує, а не гріє, освітлюючи льодом.","usage_examples":"Вводьте, коли холод і збереження є темами."}}', NULL),
('a3a15d2b-a335-52d9-a00e-e51c83b463fc', '00000000-0000-0000-0000-000000000001', 'The Stone That Speaks', 'A rock that whispers secrets and ancient knowledge to those who listen.', 'story', 'object', 'Use when seeking hidden information.', '{"en":{"name":"The Stone That Speaks","description":"A rock that whispers secrets and ancient knowledge to those who listen.","usage_examples":"Use when seeking hidden information."},"ru":{"name":"Говорящий Камень","description":"Камень, шепчущий секреты и древние знания тем, кто слушает.","usage_examples":"Используйте при поиске скрытой информации."},"ua":{"name":"Камінь, Що Говорить","description":"Камінь, що шепоче секрети і стародавні знання тим, хто слухає.","usage_examples":"Використовуйте при пошуку прихованої інформації."}}', NULL),
('de0cbfad-98a5-5173-b3c8-8f7b4e814ee8', '00000000-0000-0000-0000-000000000001', 'The Puzzle Box', 'A container that can only be opened by solving its intricate mechanism.', 'story', 'object', 'Play when cleverness is required to proceed.', '{"en":{"name":"The Puzzle Box","description":"A container that can only be opened by solving its intricate mechanism.","usage_examples":"Play when cleverness is required to proceed."},"ru":{"name":"Шкатулка-Головоломка","description":"Контейнер, который можно открыть, только разгадав его сложный механизм.","usage_examples":"Играйте, когда требуется сообразительность, чтобы продвинуться."},"ua":{"name":"Скринька-Головоломка","description":"Контейнер, який можна відкрити, тільки розгадавши його складний механізм.","usage_examples":"Грайте, коли потрібна кмітливість, щоб просунутися."}}', NULL),
('66728829-e9a6-59ef-8cbd-7d630a7a991e', '00000000-0000-0000-0000-000000000001', 'The Heart of the Machine', 'The core component that gives life to mechanical constructs.', 'story', 'object', 'Introduce when dealing with artificial life or technology.', '{"en":{"name":"The Heart of the Machine","description":"The core component that gives life to mechanical constructs.","usage_examples":"Introduce when dealing with artificial life or technology."},"ru":{"name":"Сердце Машины","description":"Основной компонент, дающий жизнь механическим конструкциям.","usage_examples":"Вводите, когда имеете дело с искусственной жизнью или технологиями."},"ua":{"name":"Серце Машини","description":"Основний компонент, що дає життя механічним конструкціям.","usage_examples":"Вводьте, коли маєте справу зі штучним життям або технологіями."}}', NULL),
('d1d80fa9-050d-588b-89df-7521f883271f', '00000000-0000-0000-0000-000000000001', 'The Thorned Rose', 'A beautiful flower that draws blood from those who grasp it.', 'story', 'object', 'Use when beauty and danger are intertwined.', '{"en":{"name":"The Thorned Rose","description":"A beautiful flower that draws blood from those who grasp it.","usage_examples":"Use when beauty and danger are intertwined."},"ru":{"name":"Шипастая Роза","description":"Прекрасный цветок, пьющий кровь тех, кто его срывает.","usage_examples":"Используйте, когда красота и опасность переплетены."},"ua":{"name":"Шипаста Троянда","description":"Прекрасна квітка, що п''є кров тих, хто її зриває.","usage_examples":"Використовуйте, коли краса і небезпека переплетені."}}', NULL),
('25293ca1-ae53-58f3-988a-663ee0d0910c', '00000000-0000-0000-0000-000000000001', 'The Whispering Locket', 'A pendant that contains voices of the departed.', 'story', 'object', 'Play when the dead have messages for the living.', '{"en":{"name":"The Whispering Locket","description":"A pendant that contains voices of the departed.","usage_examples":"Play when the dead have messages for the living."},"ru":{"name":"Шепчущий Медальон","description":"Кулон, содержащий голоса усопших.","usage_examples":"Играйте, когда у мертвых есть послания для живых."},"ua":{"name":"Медальйон, Що Шепоче","description":"Кулон, що містить голоси покійних.","usage_examples":"Грайте, коли у мертвих є послання для живих."}}', NULL),
('853b0c6d-9d3b-5e69-b4d3-276154d8f56c', '00000000-0000-0000-0000-000000000001', 'The Egg That Never Hatches', 'A mysterious shell containing something that refuses to be born.', 'story', 'object', 'Introduce when potential remains forever unrealized.', '{"en":{"name":"The Egg That Never Hatches","description":"A mysterious shell containing something that refuses to be born.","usage_examples":"Introduce when potential remains forever unrealized."},"ru":{"name":"Яйцо, Которое Никогда Не Вылупится","description":"Таинственная оболочка, содержащая что-то, что отказывается рождаться.","usage_examples":"Вводите, когда потенциал остается навсегда нереализованным."},"ua":{"name":"Яйце, Що Ніколи Не Вилупиться","description":"Таємнича оболонка, що містить щось, що відмовляється народжуватися.","usage_examples":"Вводьте, коли потенціал залишається назавжди нереалізованим."}}', NULL)
INSERT INTO "public"."cards" (id, deck_id, name, description, type, category, usage_examples, translations, image_url) VALUES
('ecba54c3-2367-5a23-8f91-f687724c2e38', '00000000-0000-0000-0000-000000000001', 'A Prophecy Revealed', 'Ancient words foretelling the future come to light, changing everything.', 'story', 'catalyst', 'Use to introduce destiny or set events in motion.', '{"en":{"name":"A Prophecy Revealed","description":"Ancient words foretelling the future come to light, changing everything.","usage_examples":"Use to introduce destiny or set events in motion."},"ru":{"name":"Раскрытое Пророчество","description":"Древние слова, предсказывающие будущее, выходят на свет, меняя все.","usage_examples":"Используйте, чтобы ввести судьбу или запустить события."},"ua":{"name":"Розкрите Пророцтво","description":"Стародавні слова, що пророкують майбутнє, виходять на світло, змінюючи все.","usage_examples":"Використовуйте, щоб ввести долю або запустити події."}}', NULL),
('18d5f89e-e63f-55b1-8dfc-2beee6c17f96', '00000000-0000-0000-0000-000000000001', 'A Secret Uncovered', 'Hidden truth comes to light, shattering assumptions and trust.', 'story', 'catalyst', 'Play when revelations change the story.', '{"en":{"name":"A Secret Uncovered","description":"Hidden truth comes to light, shattering assumptions and trust.","usage_examples":"Play when revelations change the story."},"ru":{"name":"Раскрытая Тайна","description":"Скрытая правда выходит на свет, разрушая предположения и доверие.","usage_examples":"Играйте, когда откровения меняют историю."},"ua":{"name":"Розкрита Таємниця","description":"Прихована правда виходить на світло, руйнуючи припущення і довіру.","usage_examples":"Грайте, коли одкровення змінюють історію."}}', NULL),
('3563910d-7d51-52f1-8809-bdf6d85bf8b6', '00000000-0000-0000-0000-000000000001', 'A Rescue Attempt', 'Someone tries to save another from danger, for better or worse.', 'story', 'catalyst', 'Introduce when heroism or desperation drives action.', '{"en":{"name":"A Rescue Attempt","description":"Someone tries to save another from danger, for better or worse.","usage_examples":"Introduce when heroism or desperation drives action."},"ru":{"name":"Попытка Спасения","description":"Кто-то пытается спасти другого от опасности, к лучшему или к худшему.","usage_examples":"Вводите, когда героизм или отчаяние движут действиями."},"ua":{"name":"Спроба Порятунку","description":"Хтось намагається врятувати іншого від небезпеки, на краще чи на гірше.","usage_examples":"Вводьте, коли героїзм або відчай рухають діями."}}', NULL),
('9d0dc0db-5b26-5196-b14f-eabcc3eb01b8', '00000000-0000-0000-0000-000000000001', 'A Sudden Betrayal', 'Trust is shattered as an ally reveals their true allegiance.', 'story', 'catalyst', 'Use when shocking turns are needed.', '{"en":{"name":"A Sudden Betrayal","description":"Trust is shattered as an ally reveals their true allegiance.","usage_examples":"Use when shocking turns are needed."},"ru":{"name":"Внезапное Предательство","description":"Доверие разрушено, когда союзник раскрывает свою истинную преданность.","usage_examples":"Используйте, когда нужны шокирующие повороты."},"ua":{"name":"Раптова Зрада","description":"Довіра зруйнована, коли союзник розкриває свою справжню відданість.","usage_examples":"Використовуйте, коли потрібні шокуючі повороти."}}', NULL),
('8d1df6d1-f71e-5b75-855d-25b346be3fe7', '00000000-0000-0000-0000-000000000001', 'A Forbidden Love', 'Hearts connect across boundaries that should never be crossed.', 'story', 'catalyst', 'Play when romance complicates everything.', '{"en":{"name":"A Forbidden Love","description":"Hearts connect across boundaries that should never be crossed.","usage_examples":"Play when romance complicates everything."},"ru":{"name":"Запретная Любовь","description":"Сердца соединяются через границы, которые никогда не должны быть пересечены.","usage_examples":"Играйте, когда романтика все усложняет."},"ua":{"name":"Заборонене Кохання","description":"Серця з''єднуються через кордони, які ніколи не повинні бути перетнуті.","usage_examples":"Грайте, коли романтика все ускладнює."}}', NULL),
('c9ec2659-27b6-5c58-a900-7de7d06c5bde', '00000000-0000-0000-0000-000000000001', 'A Duel at Dawn', 'Two opponents face each other in formal combat to settle their dispute.', 'story', 'catalyst', 'Introduce when honor demands satisfaction.', '{"en":{"name":"A Duel at Dawn","description":"Two opponents face each other in formal combat to settle their dispute.","usage_examples":"Introduce when honor demands satisfaction."},"ru":{"name":"Дуэль на Рассвете","description":"Два противника сталкиваются в формальном бою, чтобы разрешить свой спор.","usage_examples":"Вводите, когда честь требует сатисфакции."},"ua":{"name":"Дуель на Світанку","description":"Два супротивники стикаються у формальному бою, щоб вирішити свою суперечку.","usage_examples":"Вводьте, коли честь вимагає сатисфакції."}}', NULL),
('d366491f-ca0e-5132-9fbf-6fcff987f98f', '00000000-0000-0000-0000-000000000001', 'A Message from the Past', 'Communication from another time arrives, bearing crucial information.', 'story', 'catalyst', 'Use when history speaks to the present.', '{"en":{"name":"A Message from the Past","description":"Communication from another time arrives, bearing crucial information.","usage_examples":"Use when history speaks to the present."},"ru":{"name":"Послание из Прошлого","description":"Приходит сообщение из другого времени, несущее важную информацию.","usage_examples":"Используйте, когда история говорит с настоящим."},"ua":{"name":"Послання з Минулого","description":"Приходить повідомлення з іншого часу, що несе важливу інформацію.","usage_examples":"Використовуйте, коли історія говорить із сьогоденням."}}', NULL),
('6236c712-7e2b-58e4-977e-af2be2de90e1', '00000000-0000-0000-0000-000000000001', 'A Stranger Arrives', 'An unknown person appears, bringing change and mystery.', 'story', 'catalyst', 'Play when new elements enter the story.', '{"en":{"name":"A Stranger Arrives","description":"An unknown person appears, bringing change and mystery.","usage_examples":"Play when new elements enter the story."},"ru":{"name":"Прибытие Незнакомца","description":"Появляется неизвестный человек, принося перемены и тайну.","usage_examples":"Играйте, когда новые элементы входят в историю."},"ua":{"name":"Прибуття Незнайомця","description":"З''являється невідома людина, приносячи зміни і таємницю.","usage_examples":"Грайте, коли нові елементи входять в історію."}}', NULL),
('03888b3c-4029-5800-8dbe-37523b5d6344', '00000000-0000-0000-0000-000000000001', 'A Door Appears', 'A portal or passage manifests where none existed before.', 'story', 'catalyst', 'Introduce when new paths open.', '{"en":{"name":"A Door Appears","description":"A portal or passage manifests where none existed before.","usage_examples":"Introduce when new paths open."},"ru":{"name":"Появление Двери","description":"Портал или проход проявляется там, где раньше ничего не было.","usage_examples":"Вводите, когда открываются новые пути."},"ua":{"name":"Поява Дверей","description":"Портал або прохід проявляється там, де раніше нічого не було.","usage_examples":"Вводьте, коли відкриваються нові шляхи."}}', NULL),
('fd79e77e-c717-55e9-8826-92e4c3f9e540', '00000000-0000-0000-0000-000000000001', 'A Dream Foretold', 'A vision in sleep proves to be prophetic or significant.', 'story', 'catalyst', 'Use when the subconscious reveals truth.', '{"en":{"name":"A Dream Foretold","description":"A vision in sleep proves to be prophetic or significant.","usage_examples":"Use when the subconscious reveals truth."},"ru":{"name":"Предсказанный Сон","description":"Видение во сне оказывается пророческим или значимым.","usage_examples":"Используйте, когда подсознание раскрывает правду."},"ua":{"name":"Передбачений Сон","description":"Видіння уві сні виявляється пророчим або значущим.","usage_examples":"Використовуйте, коли підсвідомість розкриває правду."}}', NULL),
('2de9f06c-cfe4-5e34-9554-73bada95a5e1', '00000000-0000-0000-0000-000000000001', 'A Pact is Broken', 'An agreement is violated, releasing consequences.', 'story', 'catalyst', 'Play when oaths fail and chaos follows.', '{"en":{"name":"A Pact is Broken","description":"An agreement is violated, releasing consequences.","usage_examples":"Play when oaths fail and chaos follows."},"ru":{"name":"Нарушенный Договор","description":"Соглашение нарушено, высвобождая последствия.","usage_examples":"Играйте, когда клятвы рушатся и следует хаос."},"ua":{"name":"Порушений Договір","description":"Угода порушена, вивільняючи наслідки. ","usage_examples":"Грайте, коли клятви руйнуються і слідує хаос."}}', NULL),
('44d12376-ab2f-52f6-ba85-800b80428528', '00000000-0000-0000-0000-000000000001', 'A Festival Begins', 'Celebration commences, providing cover for plots or joy before disaster.', 'story', 'catalyst', 'Introduce when gathering and festivity matter.', '{"en":{"name":"A Festival Begins","description":"Celebration commences, providing cover for plots or joy before disaster.","usage_examples":"Introduce when gathering and festivity matter."},"ru":{"name":"Начало Фестиваля","description":"Начинается празднование, обеспечивающее прикрытие для заговоров или радость перед катастрофой.","usage_examples":"Вводите, когда собрания и празднества имеют значение."},"ua":{"name":"Початок Фестивалю","description":"Починається святкування, що забезпечує прикриття для змов або радість перед катастрофою.","usage_examples":"Вводьте, коли зібрання та святкування мають значення."}}', NULL),
('9a1a72f7-b972-5f51-9516-57c4042f2caf', '00000000-0000-0000-0000-000000000001', 'A War Ignites', 'Conflict erupts into open warfare, consuming all in its path.', 'story', 'catalyst', 'Use when peace ends and battle begins.', '{"en":{"name":"A War Ignites","description":"Conflict erupts into open warfare, consuming all in its path.","usage_examples":"Use when peace ends and battle begins."},"ru":{"name":"Вспыхивает Война","description":"Конфликт перерастает в открытую войну, поглощающую все на своем пути.","usage_examples":"Используйте, когда мир заканчивается и начинается битва."},"ua":{"name":"Спалахує Війна","description":"Конфлікт переростає у відкриту війну, що поглинає все на своєму шляху.","usage_examples":"Використовуйте, коли мир закінчується і починається битва."}}', NULL),
('1d5cd68b-2b7e-5695-ac25-15b0f8de4822', '00000000-0000-0000-0000-000000000001', 'A Storm Approaches', 'Dark weather heralds coming danger or change.', 'story', 'catalyst', 'Play when omens appear in nature.', '{"en":{"name":"A Storm Approaches","description":"Dark weather heralds coming danger or change.","usage_examples":"Play when omens appear in nature."},"ru":{"name":"Приближение Бури","description":"Темная погода предвещает грядущую опасность или перемены.","usage_examples":"Играйте, когда знамения появляются в природе."},"ua":{"name":"Наближення Бурі","description":"Темна погода віщує майбутню небезпеку або зміни.","usage_examples":"Грайте, коли знамення з''являються в природі."}}', NULL),
('1d0968c8-3baf-514c-971a-fa92a667cc5b', '00000000-0000-0000-0000-000000000001', 'A Child is Born', 'New life enters the world, bringing hope or prophecy.', 'story', 'catalyst', 'Introduce when birth changes everything.', '{"en":{"name":"A Child is Born","description":"New life enters the world, bringing hope or prophecy.","usage_examples":"Introduce when birth changes everything."},"ru":{"name":"Рождение Ребенка","description":"Новая жизнь входит в мир, принося надежду или пророчество.","usage_examples":"Вводите, когда рождение меняет все."},"ua":{"name":"Народження Дитини","description":"Нове життя входить у світ, приносячи надію або пророцтво.","usage_examples":"Вводьте, коли народження змінює все."}}', NULL),
('2e0b5824-74bb-5879-99f8-af79bc0a3d74', '00000000-0000-0000-0000-000000000001', 'A Hero Falls', 'A great champion is defeated or dies, leaving a void.', 'story', 'catalyst', 'Use when loss drives the narrative.', '{"en":{"name":"A Hero Falls","description":"A great champion is defeated or dies, leaving a void.","usage_examples":"Use when loss drives the narrative."},"ru":{"name":"Падение Героя","description":"Великий чемпион побежден или умирает, оставляя пустоту.","usage_examples":"Используйте, когда потеря движет повествование."},"ua":{"name":"Падіння Героя","description":"Великий чемпіон переможений або помирає, залишаючи порожнечу.","usage_examples":"Використовуйте, коли втрата рухає розповідь."}}', NULL),
('8c04ebd2-d025-5c33-82f4-5b934f1a29cd', '00000000-0000-0000-0000-000000000001', 'A Truth is Denied', 'Reality is rejected, leading to dangerous self-deception.', 'story', 'catalyst', 'Play when characters refuse to see what is.', '{"en":{"name":"A Truth is Denied","description":"Reality is rejected, leading to dangerous self-deception.","usage_examples":"Play when characters refuse to see what is."},"ru":{"name":"Отрицание Истины","description":"Реальность отвергается, что ведет к опасному самообману.","usage_examples":"Играйте, когда персонажи отказываются видеть то, что есть."},"ua":{"name":"Заперечення Істини","description":"Реальність відкидається, що веде до небезпечного самообману.","usage_examples":"Грайте, коли персонажі відмовляються бачити те, що є."}}', NULL),
('69018a8d-3d07-5b5c-86d2-dad9808343d4', '00000000-0000-0000-0000-000000000001', 'A Monster Awakens', 'A terrible creature stirs from slumber, threatening all.', 'story', 'catalyst', 'Introduce when ancient threats return.', '{"en":{"name":"A Monster Awakens","description":"A terrible creature stirs from slumber, threatening all.","usage_examples":"Introduce when ancient threats return."},"ru":{"name":"Пробуждение Монстра","description":"Ужасное существо пробуждается от сна, угрожая всем.","usage_examples":"Вводите, когда древние угрозы возвращаются."},"ua":{"name":"Пробудження Монстра","description":"Жахлива істота прокидається від сну, погрожуючи всім.","usage_examples":"Вводьте, коли стародавні загрози повертаються."}}', NULL),
('86c0f538-1b20-5174-a7e8-1cacf3fb813c', '00000000-0000-0000-0000-000000000001', 'A Spell Backfires', 'Magic goes wrong, creating unintended consequences.', 'story', 'catalyst', 'Use when power escapes control.', '{"en":{"name":"A Spell Backfires","description":"Magic goes wrong, creating unintended consequences.","usage_examples":"Use when power escapes control."},"ru":{"name":"Заклинание Дает Осечку","description":"Магия идет не так, создавая непреднамеренные последствия.","usage_examples":"Используйте, когда сила выходит из-под контроля."},"ua":{"name":"Заклинання Дає Осічку","description":"Магія йде не так, створюючи ненавмисні наслідки.","usage_examples":"Використовуйте, коли сила виходить з-під контролю."}}', NULL),
('8e64f9af-4dc8-5998-be43-54a87ee758a0', '00000000-0000-0000-0000-000000000001', 'A Clock Strikes Thirteen', 'Time behaves impossibly, signaling something is wrong.', 'story', 'catalyst', 'Play when reality breaks down.', '{"en":{"name":"A Clock Strikes Thirteen","description":"Time behaves impossibly, signaling something is wrong.","usage_examples":"Play when reality breaks down."},"ru":{"name":"Часы Бьют Тринадцать","description":"Время ведет себя невозможно, сигнализируя, что что-то не так.","usage_examples":"Играйте, когда реальность ломается."},"ua":{"name":"Годинник Б''є Тринадцять","description":"Час поводиться неможливо, сигналізуючи, що щось не так.","usage_examples":"Грайте, коли реальність ламається."}}', NULL),
('f8b97505-5563-53ae-9002-486dcb730eac', '00000000-0000-0000-0000-000000000001', 'A Mask is Removed', 'True identity is revealed, for good or ill.', 'story', 'catalyst', 'Introduce when deception ends.', '{"en":{"name":"A Mask is Removed","description":"True identity is revealed, for good or ill.","usage_examples":"Introduce when deception ends."},"ru":{"name":"Маска Снята","description":"Истинная личность раскрыта, к добру или к худу.","usage_examples":"Вводите, когда обман заканчивается."},"ua":{"name":"Маска Знята","description":"Справжня особистість розкрита, до добра чи до лиха.","usage_examples":"Вводьте, коли обман закінчується."}}', NULL),
('25392176-cf18-5175-a7eb-d03d2fe38df6', '00000000-0000-0000-0000-000000000001', 'A Sacrifice is Made', 'Someone gives up something precious for a greater cause.', 'story', 'catalyst', 'Use when cost and value collide.', '{"en":{"name":"A Sacrifice is Made","description":"Someone gives up something precious for a greater cause.","usage_examples":"Use when cost and value collide."},"ru":{"name":"Принесена Жертва","description":"Кто-то отказывается от чего-то драгоценного ради великой цели.","usage_examples":"Используйте, когда цена и ценность сталкиваются."},"ua":{"name":"Принесена Жертва","description":"Хтось відмовляється від чогось дорогоцінного заради великої мети.","usage_examples":"Використовуйте, коли ціна і цінність стикаються."}}', NULL),
('c7848e7a-9be0-5912-a240-766baae8c0cd', '00000000-0000-0000-0000-000000000001', 'A Prison is Breached', 'Captives escape or invaders break through defenses.', 'story', 'catalyst', 'Play when containment fails.', '{"en":{"name":"A Prison is Breached","description":"Captives escape or invaders break through defenses.","usage_examples":"Play when containment fails."},"ru":{"name":"Тюрьма Взломана","description":"Пленники сбегают или захватчики прорываются через защиту.","usage_examples":"Играйте, когда сдерживание не удается."},"ua":{"name":"В''язниця Зламана","description":"Полонені тікають або загарбники прориваються через захист.","usage_examples":"Грайте, коли стримування не вдається."}}', NULL),
('d4f238ed-c07b-5b43-98b8-99b7aa50908c', '00000000-0000-0000-0000-000000000001', 'A Trial is Called', 'Judgment is demanded, and truth must be determined.', 'story', 'catalyst', 'Introduce when justice is sought.', '{"en":{"name":"A Trial is Called","description":"Judgment is demanded, and truth must be determined.","usage_examples":"Introduce when justice is sought."},"ru":{"name":"Назначен Суд","description":"Требуется правосудие, и истина должна быть установлена.","usage_examples":"Вводите, когда ищется справедливость."},"ua":{"name":"Призначено Суд","description":"Вимагається правосуддя, і істина повинна бути встановлена.","usage_examples":"Вводьте, коли шукається справедливість."}}', NULL),
('8001c919-da12-511b-b01a-a9dcca4226c6', '00000000-0000-0000-0000-000000000001', 'A God Demands Tribute', 'Divine power requires payment or worship.', 'story', 'catalyst', 'Use when the sacred makes demands.', '{"en":{"name":"A God Demands Tribute","description":"Divine power requires payment or worship.","usage_examples":"Use when the sacred makes demands."},"ru":{"name":"Бог Требует Дани","description":"Божественная сила требует платы или поклонения.","usage_examples":"Используйте, когда священное предъявляет требования."},"ua":{"name":"Бог Вимагає Данини","description":"Божественна сила вимагає плати або поклоніння.","usage_examples":"Використовуйте, коли священне висуває вимоги."}}', NULL),
('1e389074-87f3-550a-9db2-15a37b5c31c6', '00000000-0000-0000-0000-000000000001', 'A Friend is Lost', 'A companion disappears, dies, or is taken.', 'story', 'catalyst', 'Play when grief drives action.', '{"en":{"name":"A Friend is Lost","description":"A companion disappears, dies, or is taken.","usage_examples":"Play when grief drives action."},"ru":{"name":"Потеря Друга","description":"Спутник исчезает, умирает или похищен.","usage_examples":"Играйте, когда горе движет действиями."},"ua":{"name":"Втрата Друга","description":"Супутник зникає, помирає або викрадений.","usage_examples":"Грайте, коли горе рухає діями."}}', NULL),
('6febd0a4-f08f-5ad8-a67e-1493605cfb03', '00000000-0000-0000-0000-000000000001', 'A New Power Rises', 'A force or person gains strength and influence.', 'story', 'catalyst', 'Introduce when the balance shifts.', '{"en":{"name":"A New Power Rises","description":"A force or person gains strength and influence.","usage_examples":"Introduce when the balance shifts."},"ru":{"name":"Восстание Новой Силы","description":"Сила или человек набирает мощь и влияние.","usage_examples":"Вводите, когда баланс смещается."},"ua":{"name":"Повстання Нової Сили","description":"Сила або людина набирає міць і вплив.","usage_examples":"Вводьте, коли баланс зміщується."}}', NULL),
('b7766148-71b8-5bba-9f93-871763ac1a6e', '00000000-0000-0000-0000-000000000001', 'A Letter is Delivered', 'Written words arrive, carrying news that changes plans.', 'story', 'catalyst', 'Use when communication alters the course.', '{"en":{"name":"A Letter is Delivered","description":"Written words arrive, carrying news that changes plans.","usage_examples":"Use when communication alters the course."},"ru":{"name":"Письмо Доставлено","description":"Приходят письменные слова, несущие новости, которые меняют планы.","usage_examples":"Используйте, когда общение меняет курс."},"ua":{"name":"Лист Доставлено","description":"Приходять письмові слова, що несуть новини, які змінюють плани.","usage_examples":"Використовуйте, коли спілкування змінює курс."}}', NULL),
('74698f3e-a7d2-5a85-b74b-8d9c1617cd54', '00000000-0000-0000-0000-000000000001', 'A Weapon is Found', 'A tool of power is discovered, offering new possibilities.', 'story', 'catalyst', 'Play when means become available.', '{"en":{"name":"A Weapon is Found","description":"A tool of power is discovered, offering new possibilities.","usage_examples":"Play when means become available."},"ru":{"name":"Оружие Найдено","description":"Обнаружен инструмент силы, предлагающий новые возможности.","usage_examples":"Играйте, когда средства становятся доступными."},"ua":{"name":"Зброю Знайдено","description":"Виявлено інструмент сили, що пропонує нові можливості.","usage_examples":"Грайте, коли засоби стають доступними."}}', NULL),
('e0f933d2-aae7-53c0-b02c-d6aabca8d7ac', '00000000-0000-0000-0000-000000000001', 'A Memory Returns', 'Forgotten knowledge resurfaces, illuminating the present.', 'story', 'catalyst', 'Introduce when the past clarifies now.', '{"en":{"name":"A Memory Returns","description":"Forgotten knowledge resurfaces, illuminating the present.","usage_examples":"Introduce when the past clarifies now."},"ru":{"name":"Возвращение Памяти","description":"Забытое знание всплывает, освещая настоящее.","usage_examples":"Вводите, когда прошлое проясняет «сейчас»."},"ua":{"name":"Повернення Пам''яті","description":"Забуте знання спливає, висвітлюючи сьогодення.","usage_examples":"Вводьте, коли минуле прояснює «зараз»."}}', NULL),
('998e33d4-428f-5751-9de6-c85ee4f638c6', '00000000-0000-0000-0000-000000000001', 'A Portal Opens', 'A gateway between places or worlds becomes accessible.', 'story', 'catalyst', 'Use when travel or invasion begins.', '{"en":{"name":"A Portal Opens","description":"A gateway between places or worlds becomes accessible.","usage_examples":"Use when travel or invasion begins."},"ru":{"name":"Открытие Портала","description":"Врата между местами или мирами становятся доступными.","usage_examples":"Используйте, когда начинается путешествие или вторжение."},"ua":{"name":"Відкриття Порталу","description":"Брама між місцями або світами стає доступною.","usage_examples":"Використовуйте, коли починається подорож або вторгнення."}}', NULL),
('d959de40-73fd-581c-a208-8bd147e0593f', '00000000-0000-0000-0000-000000000001', 'A Curse is Cast', 'Dark magic is invoked, bringing misfortune.', 'story', 'catalyst', 'Play when supernatural doom arrives.', '{"en":{"name":"A Curse is Cast","description":"Dark magic is invoked, bringing misfortune.","usage_examples":"Play when supernatural doom arrives."},"ru":{"name":"Наложено Проклятие","description":"Темная магия призвана, принося несчастье.","usage_examples":"Играйте, когда сверхъестественный рок прибывает."},"ua":{"name":"Накладено Прокляття","description":"Темна магія призвана, приносячи нещастя.","usage_examples":"Грайте, коли надприродний фатум прибуває."}}', NULL),
('1950a98b-0bcd-5c59-9180-66c517552dfd', '00000000-0000-0000-0000-000000000001', 'A Kingdom Crumbles', 'Political power collapses, creating chaos.', 'story', 'catalyst', 'Introduce when order fails.', '{"en":{"name":"A Kingdom Crumbles","description":"Political power collapses, creating chaos.","usage_examples":"Introduce when order fails."},"ru":{"name":"Королевство Рушится","description":"Политическая власть рушится, создавая хаос.","usage_examples":"Вводите, когда порядок терпит неудачу."},"ua":{"name":"Королівство Руйнується","description":"Політична влада руйнується, створюючи хаос.","usage_examples":"Вводьте, коли порядок зазнає невдачі."}}', NULL),
('28313719-4489-5368-aa40-54b1ad15b31c', '00000000-0000-0000-0000-000000000001', 'A Stranger is Trusted', 'Faith is placed in an unknown person, with uncertain results.', 'story', 'catalyst', 'Use when risk and hope combine.', '{"en":{"name":"A Stranger is Trusted","description":"Faith is placed in an unknown person, with uncertain results.","usage_examples":"Use when risk and hope combine."},"ru":{"name":"Доверие Незнакомцу","description":"Вера возлагается на неизвестного человека с неопределенными результатами.","usage_examples":"Используйте, когда риск и надежда сочетаются."},"ua":{"name":"Довіра Незнайомцю","description":"Віра покладається на невідому людину з невизначеними результатами.","usage_examples":"Використовуйте, коли ризик і надія поєднуються."}}', NULL),
('4118583e-ea33-5c8e-9b5c-5b97ce7813a2', '00000000-0000-0000-0000-000000000001', 'A Lie is Believed', 'Falsehood is accepted as truth, leading astray.', 'story', 'catalyst', 'Play when deception succeeds.', '{"en":{"name":"A Lie is Believed","description":"Falsehood is accepted as truth, leading astray.","usage_examples":"Play when deception succeeds."},"ru":{"name":"Вера в Ложь","description":"Ложь принимается за правду, уводя в сторону.","usage_examples":"Играйте, когда обман удается."},"ua":{"name":"Віра в Брехню","description":"Брехня приймається за правду, ведучи вбік.","usage_examples":"Грайте, коли обман вдається."}}', NULL),
('10c70667-f8d5-528b-9d7c-e25fa6d31da5', '00000000-0000-0000-0000-000000000001', 'A Fire Spreads', 'Flames consume, destroying or purifying.', 'story', 'catalyst', 'Introduce when destruction advances.', '{"en":{"name":"A Fire Spreads","description":"Flames consume, destroying or purifying.","usage_examples":"Introduce when destruction advances."},"ru":{"name":"Огонь Распространяется","description":"Пламя пожирает, уничтожая или очищая.","usage_examples":"Вводите, когда разрушение наступает."},"ua":{"name":"Вогонь Поширюється","description":"Полум''я пожирає, знищуючи або очищаючи.","usage_examples":"Вводьте, коли руйнування настає."}}', NULL),
('33ea0355-8806-5dc4-9764-42627be3f5f4', '00000000-0000-0000-0000-000000000001', 'A Deal is Struck', 'An agreement is made, binding parties to its terms.', 'story', 'catalyst', 'Use when bargains shape fate.', '{"en":{"name":"A Deal is Struck","description":"An agreement is made, binding parties to its terms.","usage_examples":"Use when bargains shape fate."},"ru":{"name":"Сделка Заключена","description":"Соглашение достигнуто, связывая стороны его условиями.","usage_examples":"Используйте, когда сделки формируют судьбу."},"ua":{"name":"Угода Укладена","description":"Угода досягнута, пов''язуючи сторони її умовами.","usage_examples":"Використовуйте, коли угоди формують долю."}}', NULL),
('22f43c22-4c2e-5370-88f2-2f056c16959e', '00000000-0000-0000-0000-000000000001', 'A Secret Passage Found', 'A hidden way is discovered, offering escape or infiltration.', 'story', 'catalyst', 'Play when new routes appear.', '{"en":{"name":"A Secret Passage Found","description":"A hidden way is discovered, offering escape or infiltration.","usage_examples":"Play when new routes appear."},"ru":{"name":"Найден Тайный Проход","description":"Обнаружен скрытый путь, предлагающий побег или проникновение.","usage_examples":"Играйте, когда появляются новые маршруты."},"ua":{"name":"Знайдено Таємний Прохід","description":"Виявлено прихований шлях, що пропонує втечу або проникнення.","usage_examples":"Грайте, коли з''являються нові маршрути."}}', NULL),
('63e1593e-49a8-507e-8265-e9d3ce4bfa8d', '00000000-0000-0000-0000-000000000001', 'A Song is Sung', 'Music is performed, carrying power or emotion.', 'story', 'catalyst', 'Introduce when art affects reality.', '{"en":{"name":"A Song is Sung","description":"Music is performed, carrying power or emotion.","usage_examples":"Introduce when art affects reality."},"ru":{"name":"Песня Спета","description":"Музыка исполняется, неся силу или эмоции.","usage_examples":"Вводите, когда искусство влияет на реальность."},"ua":{"name":"Пісня Заспівана","description":"Музика виконується, несучи силу або емоції.","usage_examples":"Вводьте, коли мистецтво впливає на реальність."}}', NULL),
('31af7022-fd1b-57f6-8e62-024849d1f30f', '00000000-0000-0000-0000-000000000001', 'A Choice Must Be Made', 'A decision point arrives where the path forward diverges.', 'story', 'catalyst', 'Use when free will determines destiny.', '{"en":{"name":"A Choice Must Be Made","description":"A decision point arrives where the path forward diverges.","usage_examples":"Use when free will determines destiny."},"ru":{"name":"Выбор Должен Быть Сделан","description":"Наступает момент решения, где путь вперед расходится.","usage_examples":"Используйте, когда свободная воля определяет судьбу."},"ua":{"name":"Вибір Повинен Бути Зроблений","description":"Настає момент рішення, де шлях вперед розходиться.","usage_examples":"Використовуйте, коли вільна воля визначає долю."}}', NULL)
INSERT INTO "public"."cards" (id, deck_id, name, description, type, category, usage_examples, translations, image_url) VALUES
('364395e8-8f6d-5733-8d38-343f29dde9a9', '00000000-0000-0000-0000-000000000001', 'Bravery in Doubt', 'Courage that persists even when fear and uncertainty threaten to overwhelm.', 'story', 'trait', 'Use when characters must act despite their fears.', '{"en":{"name":"Bravery in Doubt","description":"Courage that persists even when fear and uncertainty threaten to overwhelm.","usage_examples":"Use when characters must act despite their fears."},"ru":{"name":"Храбрость в Сомнении","description":"Мужество, которое сохраняется, даже когда страх и неуверенность грозят переполнить.","usage_examples":"Используйте, когда персонажи должны действовать вопреки своим страхам."},"ua":{"name":"Хоробрість у Сумніві","description":"Мужність, що зберігається, навіть коли страх і невпевненість загрожують переповнити.","usage_examples":"Використовуйте, коли персонажі повинні діяти всупереч своїм страхам."}}', NULL),
('66bd96ff-992a-5cb9-84f8-faab7abc8275', '00000000-0000-0000-0000-000000000001', 'Greed Unleashed', 'Insatiable desire for wealth or power that consumes all other concerns.', 'story', 'trait', 'Play when avarice drives destructive behavior.', '{"en":{"name":"Greed Unleashed","description":"Insatiable desire for wealth or power that consumes all other concerns.","usage_examples":"Play when avarice drives destructive behavior."},"ru":{"name":"Развязанная Жадность","description":"Ненасытное желание богатства или власти, поглощающее все остальные заботы.","usage_examples":"Играйте, когда алчность движет разрушительным поведением."},"ua":{"name":"Розв''язана Жадібність","description":"Ненаситне бажання багатства або влади, що поглинає всі інші турботи.","usage_examples":"Грайте, коли жадібність рухає руйнівною поведінкою."}}', NULL),
('230cdf75-185d-51af-a70e-1c398bd048f5', '00000000-0000-0000-0000-000000000001', 'Hope Rekindled', 'The return of optimism after it seemed lost forever.', 'story', 'trait', 'Introduce when light appears in darkness.', '{"en":{"name":"Hope Rekindled","description":"The return of optimism after it seemed lost forever.","usage_examples":"Introduce when light appears in darkness."},"ru":{"name":"Возрожденная Надежда","description":"Возвращение оптимизма после того, как он казался потерянным навсегда.","usage_examples":"Вводите, когда свет появляется во тьме."},"ua":{"name":"Відроджена Надія","description":"Повернення оптимізму після того, як він здавався втраченим назавжди.","usage_examples":"Вводьте, коли світло з''являється в темряві."}}', NULL),
('ee93c3aa-ae7a-5527-8979-548524e237b0', '00000000-0000-0000-0000-000000000001', 'Loneliness Echoed', 'Profound isolation that resonates through actions and choices.', 'story', 'trait', 'Use when exploring solitude and its effects.', '{"en":{"name":"Loneliness Echoed","description":"Profound isolation that resonates through actions and choices.","usage_examples":"Use when exploring solitude and its effects."},"ru":{"name":"Эхо Одиночества","description":"Глубокая изоляция, резонирующая через действия и выбор.","usage_examples":"Используйте при исследовании одиночества и его последствий."},"ua":{"name":"Відлуння Самотності","description":"Глибока ізоляція, що резонує через дії та вибір.","usage_examples":"Використовуйте при дослідженні самотності та її наслідків."}}', NULL),
('8e232824-7e44-574d-b74c-41c089ab4399', '00000000-0000-0000-0000-000000000001', 'Love Unspoken', 'Deep affection that remains unexpressed, shaping events from silence.', 'story', 'trait', 'Play when hidden feelings matter.', '{"en":{"name":"Love Unspoken","description":"Deep affection that remains unexpressed, shaping events from silence.","usage_examples":"Play when hidden feelings matter."},"ru":{"name":"Невысказанная Любовь","description":"Глубокая привязанность, остающаяся невыраженной, формирующая события из тишины.","usage_examples":"Играйте, когда скрытые чувства имеют значение."},"ua":{"name":"Невисловлене Кохання","description":"Глибока прихильність, що залишається невираженою, формуючи події з тиші.","usage_examples":"Грайте, коли приховані почуття мають значення."}}', NULL),
('a2df2489-c677-5713-ba7f-21f83e5f9b0c', '00000000-0000-0000-0000-000000000001', 'Pride Before the Fall', 'Arrogance that leads inevitably to downfall.', 'story', 'trait', 'Introduce when hubris precedes disaster.', '{"en":{"name":"Pride Before the Fall","description":"Arrogance that leads inevitably to downfall.","usage_examples":"Introduce when hubris precedes disaster."},"ru":{"name":"Гордыня перед Падением","description":"Высокомерие, неизбежно ведущее к краху.","usage_examples":"Вводите, когда гордыня предшествует катастрофе."},"ua":{"name":"Гординя перед Падінням","description":"Зарозумілість, що неминуче веде до краху.","usage_examples":"Вводьте, коли гординя передує катастрофі."}}', NULL),
('d53700b5-9ee6-5a31-a78d-6ba3a9978c80', '00000000-0000-0000-0000-000000000001', 'Redemption Sought', 'The active pursuit of forgiveness and restoration after wrongdoing.', 'story', 'trait', 'Use when characters seek to atone.', '{"en":{"name":"Redemption Sought","description":"The active pursuit of forgiveness and restoration after wrongdoing.","usage_examples":"Use when characters seek to atone."},"ru":{"name":"Поиск Искупления","description":"Активное стремление к прощению и восстановлению после проступка.","usage_examples":"Используйте, когда персонажи стремятся искупить вину."},"ua":{"name":"Пошук Спокути","description":"Активне прагнення до прощення та відновлення після проступку.","usage_examples":"Використовуйте, коли персонажі прагнуть спокутувати провину."}}', NULL),
('77104b6c-7682-57cb-9ea1-d6c226bb2804', '00000000-0000-0000-0000-000000000001', 'Trust Betrayed', 'The shattering of faith in another, leaving deep wounds.', 'story', 'trait', 'Play when loyalty is violated.', '{"en":{"name":"Trust Betrayed","description":"The shattering of faith in another, leaving deep wounds.","usage_examples":"Play when loyalty is violated."},"ru":{"name":"Преданное Доверие","description":"Разрушение веры в другого, оставляющее глубокие раны.","usage_examples":"Играйте, когда верность нарушена."},"ua":{"name":"Зраджена Довіра","description":"Руйнування віри в іншого, що залишає глибокі рани. ","usage_examples":"Грайте, коли вірність порушена."}}', NULL),
('515fdd29-f30d-5675-b752-97285fb14469', '00000000-0000-0000-0000-000000000001', 'Duty Over Desire', 'Obligation chosen above personal wants and needs.', 'story', 'trait', 'Introduce when sacrifice is required.', '{"en":{"name":"Duty Over Desire","description":"Obligation chosen above personal wants and needs.","usage_examples":"Introduce when sacrifice is required."},"ru":{"name":"Долг Превыше Желания","description":"Обязательство, выбранное вместо личных желаний и потребностей.","usage_examples":"Вводите, когда требуется жертва."},"ua":{"name":"Обов''язок Понад Бажання","description":"Зобов''язання, обране замість особистих бажань і потреб.","usage_examples":"Вводьте, коли потрібна жертва."}}', NULL),
('988518d8-c78e-51ed-8061-aaf7fe191fed', '00000000-0000-0000-0000-000000000001', 'Fear of the Unknown', 'Terror of what cannot be seen or understood.', 'story', 'trait', 'Use when mystery breeds dread.', '{"en":{"name":"Fear of the Unknown","description":"Terror of what cannot be seen or understood.","usage_examples":"Use when mystery breeds dread."},"ru":{"name":"Страх Неизвестного","description":"Ужас перед тем, что нельзя увидеть или понять.","usage_examples":"Используйте, когда тайна порождает страх."},"ua":{"name":"Страх Невідомого","description":"Жах перед тим, що не можна побачити або зрозуміти.","usage_examples":"Використовуйте, коли таємниця породжує страх."}}', NULL),
('fd23c0fd-6df8-5371-920b-62207eabbf6c', '00000000-0000-0000-0000-000000000001', 'Ambition Without End', 'Drive to achieve that knows no limits or satisfaction.', 'story', 'trait', 'Play when aspiration becomes dangerous.', '{"en":{"name":"Ambition Without End","description":"Drive to achieve that knows no limits or satisfaction.","usage_examples":"Play when aspiration becomes dangerous."},"ru":{"name":"Бесконечные Амбиции","description":"Стремление к достижениям, не знающее границ или удовлетворения.","usage_examples":"Играйте, когда стремление становится опасным."},"ua":{"name":"Нескінченні Амбіції","description":"Прагнення до досягнень, що не знає меж або задоволення.","usage_examples":"Грайте, коли прагнення стає небезпечним."}}', NULL),
('2018b30e-16ae-5377-b5f7-5f9382866df8', '00000000-0000-0000-0000-000000000001', 'Kindness in Darkness', 'Compassion that shines even in the bleakest circumstances.', 'story', 'trait', 'Introduce when goodness persists.', '{"en":{"name":"Kindness in Darkness","description":"Compassion that shines even in the bleakest circumstances.","usage_examples":"Introduce when goodness persists."},"ru":{"name":"Доброта во Тьме","description":"Сострадание, которое сияет даже в самых мрачных обстоятельствах.","usage_examples":"Вводите, когда доброта сохраняется."},"ua":{"name":"Доброта у Темряві","description":"Співчуття, що сяє навіть у найпохмуріших обставинах. ","usage_examples":"Вводьте, коли доброта зберігається."}}', NULL),
('87ce4b9a-fcf5-5aa6-bbc4-fca1265cc79c', '00000000-0000-0000-0000-000000000001', 'Guilt That Festers', 'Remorse that grows and corrupts over time.', 'story', 'trait', 'Use when past wrongs haunt the present.', '{"en":{"name":"Guilt That Festers","description":"Remorse that grows and corrupts over time.","usage_examples":"Use when past wrongs haunt the present."},"ru":{"name":"Гложущая Вина","description":"Раскаяние, которое растет и развращает со временем.","usage_examples":"Используйте, когда прошлые ошибки преследуют настоящее."},"ua":{"name":"Провина, Що Гризе","description":"Каяття, що росте і розбещує з часом.","usage_examples":"Використовуйте, коли минулі помилки переслідують сьогодення."}}', NULL),
('74104b58-c72c-54f6-aeb8-a3dc5ee269d2', '00000000-0000-0000-0000-000000000001', 'Joy in Small Things', 'The ability to find happiness in simple pleasures.', 'story', 'trait', 'Play when appreciation matters.', '{"en":{"name":"Joy in Small Things","description":"The ability to find happiness in simple pleasures.","usage_examples":"Play when appreciation matters."},"ru":{"name":"Радость в Мелочах","description":"Способность находить счастье в простых удовольствиях.","usage_examples":"Играйте, когда важна признательность."},"ua":{"name":"Радість у Дрібницях","description":"Здатність знаходити щастя в простих задоволеннях.","usage_examples":"Грайте, коли важлива вдячність."}}', NULL),
('091eb91e-ee34-5174-8fe7-baf8c245655a', '00000000-0000-0000-0000-000000000001', 'Rage Unleashed', 'Fury that breaks free and consumes everything.', 'story', 'trait', 'Introduce when anger takes control.', '{"en":{"name":"Rage Unleashed","description":"Fury that breaks free and consumes everything.","usage_examples":"Introduce when anger takes control."},"ru":{"name":"Развязанная Ярость","description":"Гнев, который вырывается на свободу и поглощает все.","usage_examples":"Вводите, когда гнев берет контроль."},"ua":{"name":"Розв''язана Лють","description":"Гнів, що виривається на волю і поглинає все.","usage_examples":"Вводьте, коли гнів бере контроль."}}', NULL),
('79edf62a-9644-5061-bf4e-16ddb987e1be', '00000000-0000-0000-0000-000000000001', 'Honor Above All', 'Integrity maintained regardless of cost.', 'story', 'trait', 'Use when principles are tested.', '{"en":{"name":"Honor Above All","description":"Integrity maintained regardless of cost.","usage_examples":"Use when principles are tested."},"ru":{"name":"Честь Превыше Всего","description":"Честность сохраняется независимо от цены.","usage_examples":"Используйте, когда принципы подвергаются испытанию."},"ua":{"name":"Честь Понад Усе","description":"Чесність зберігається незалежно від ціни.","usage_examples":"Використовуйте, коли принципи піддаються випробуванню."}}', NULL),
('14bd708e-bc78-54f9-80dc-fbc38b32fe7b', '00000000-0000-0000-0000-000000000001', 'Curiosity Unchecked', 'The desire to know that leads into danger.', 'story', 'trait', 'Play when investigation brings peril.', '{"en":{"name":"Curiosity Unchecked","description":"The desire to know that leads into danger.","usage_examples":"Play when investigation brings peril."},"ru":{"name":"Необузданное Любопытство","description":"Желание знать, ведущее к опасности.","usage_examples":"Играйте, когда расследование приносит беду."},"ua":{"name":"Нестримна Допитливість","description":"Бажання знати, що веде до небезпеки.","usage_examples":"Грайте, коли розслідування приносить біду."}}', NULL),
('048302ae-09f6-58ac-911c-72e01c9e1a3a', '00000000-0000-0000-0000-000000000001', 'Faith in the Impossible', 'Belief that persists despite all evidence to the contrary.', 'story', 'trait', 'Introduce when hope defies reason.', '{"en":{"name":"Faith in the Impossible","description":"Belief that persists despite all evidence to the contrary.","usage_examples":"Introduce when hope defies reason."},"ru":{"name":"Вера в Невозможное","description":"Убеждение, которое сохраняется вопреки всем доказательствам обратного.","usage_examples":"Вводите, когда надежда бросает вызов разуму."},"ua":{"name":"Віра в Неможливе","description":"Переконання, що зберігається всупереч усім доказам зворотного.","usage_examples":"Вводьте, коли надія кидає виклик розуму."}}', NULL),
('18a7a741-6e30-5243-b4e4-b656323cff95', '00000000-0000-0000-0000-000000000001', 'Regret That Haunts', 'Sorrow over past choices that cannot be escaped.', 'story', 'trait', 'Use when the past weighs heavily.', '{"en":{"name":"Regret That Haunts","description":"Sorrow over past choices that cannot be escaped.","usage_examples":"Use when the past weighs heavily."},"ru":{"name":"Преследующее Сожаление","description":"Печаль о прошлом выборе, от которого нельзя убежать.","usage_examples":"Используйте, когда прошлое тяжело давит."},"ua":{"name":"Жаль, Що Переслідує","description":"Печаль про минулий вибір, від якого не можна втекти.","usage_examples":"Використовуйте, коли минуле важко тисне."}}', NULL),
('51d58376-a97b-5732-b228-db59c0e72db0', '00000000-0000-0000-0000-000000000001', 'Sacrifice for Love', 'Giving up what matters most for those we cherish.', 'story', 'trait', 'Play when love demands everything.', '{"en":{"name":"Sacrifice for Love","description":"Giving up what matters most for those we cherish.","usage_examples":"Play when love demands everything."},"ru":{"name":"Жертва ради Любви","description":"Отказ от самого важного ради тех, кого мы дорожим.","usage_examples":"Играйте, когда любовь требует всего."},"ua":{"name":"Жертва заради Любові","description":"Відмова від найважливішого заради тих, кого ми цінуємо.","usage_examples":"Грайте, коли любов вимагає всього."}}', NULL),
('274e8700-dadb-58e3-bd86-3afad860fc0b', '00000000-0000-0000-0000-000000000001', 'Obsession Consumes', 'Single-minded focus that destroys balance and reason.', 'story', 'trait', 'Introduce when fixation becomes destructive.', '{"en":{"name":"Obsession Consumes","description":"Single-minded focus that destroys balance and reason.","usage_examples":"Introduce when fixation becomes destructive."},"ru":{"name":"Поглощающая Одержимость","description":"Однонаправленная концентрация, разрушающая баланс и разум.","usage_examples":"Вводите, когда фиксация становится разрушительной."},"ua":{"name":"Одержимість, Що Поглинає","description":"Односпрямована концентрація, що руйнує баланс і розум.","usage_examples":"Вводьте, коли фіксація стає руйнівною."}}', NULL),
('a27cd393-0673-50db-97e7-48dadba14c3c', '00000000-0000-0000-0000-000000000001', 'Loyalty Beyond Death', 'Faithfulness that transcends even mortality.', 'story', 'trait', 'Use when devotion knows no bounds.', '{"en":{"name":"Loyalty Beyond Death","description":"Faithfulness that transcends even mortality.","usage_examples":"Use when devotion knows no bounds."},"ru":{"name":"Верность за Гранью Смерти","description":"Преданность, превосходящая даже смертность.","usage_examples":"Используйте, когда преданность не знает границ."},"ua":{"name":"Вірність за Межею Смерті","description":"Відданість, що перевершує навіть смертність.","usage_examples":"Використовуйте, коли відданість не знає меж."}}', NULL),
('aa01f401-cfb4-5078-83e1-39775a33f883', '00000000-0000-0000-0000-000000000001', 'Innocence Lost', 'The painful transition from naivety to harsh awareness.', 'story', 'trait', 'Play when corruption of purity occurs.', '{"en":{"name":"Innocence Lost","description":"The painful transition from naivety to harsh awareness.","usage_examples":"Play when corruption of purity occurs."},"ru":{"name":"Потерянная Невинность","description":"Болезненный переход от наивности к суровому осознанию.","usage_examples":"Играйте, когда происходит развращение чистоты."},"ua":{"name":"Втрачена Невинність","description":"Болісний перехід від наївності до суворого усвідомлення.","usage_examples":"Грайте, коли відбувається розбещення чистоти."}}', NULL),
('0217ad9d-32be-5423-abaa-6fe6d20a7e0d', '00000000-0000-0000-0000-000000000001', 'Courage in Silence', 'Bravery expressed through quiet endurance rather than bold action.', 'story', 'trait', 'Introduce when strength is subtle.', '{"en":{"name":"Courage in Silence","description":"Bravery expressed through quiet endurance rather than bold action.","usage_examples":"Introduce when strength is subtle."},"ru":{"name":"Мужество в Тишине","description":"Храбрость, выраженная через тихое терпение, а не смелые действия.","usage_examples":"Вводите, когда сила тонка."},"ua":{"name":"Мужність у Тиші","description":"Хоробрість, виражена через тихе терпіння, а не сміливі дії.","usage_examples":"Вводьте, коли сила тонка."}}', NULL),
('440448ac-d845-5b18-95e8-06d49b4f43ee', '00000000-0000-0000-0000-000000000001', 'Grief That Transforms', 'Sorrow that changes the mourner fundamentally.', 'story', 'trait', 'Use when loss reshapes identity.', '{"en":{"name":"Grief That Transforms","description":"Sorrow that changes the mourner fundamentally.","usage_examples":"Use when loss reshapes identity."},"ru":{"name":"Горе, Которое Трансформирует","description":"Печаль, которая фундаментально меняет скорбящего.","usage_examples":"Используйте, когда потеря меняет идентичность."},"ua":{"name":"Горе, Що Трансформує","description":"Печаль, яка фундаментально змінює скорботного.","usage_examples":"Використовуйте, коли втрата змінює ідентичність."}}', NULL),
('1c9b5e45-bdc9-5ecf-a502-cf6f6d7c2a53', '00000000-0000-0000-0000-000000000001', 'Arrogance Punished', 'Pride meeting its inevitable consequences.', 'story', 'trait', 'Play when comeuppance arrives.', '{"en":{"name":"Arrogance Punished","description":"Pride meeting its inevitable consequences.","usage_examples":"Play when comeuppance arrives."},"ru":{"name":"Наказанное Высокомерие","description":"Гордыня встречает свои неизбежные последствия.","usage_examples":"Играйте, когда наступает возмездие."},"ua":{"name":"Покарана Зарозумілість","description":"Гординя зустрічає свої неминучі наслідки.","usage_examples":"Грайте, коли настає відплата."}}', NULL),
('d9afcb87-9fcb-50d1-a10a-a8790f5245bc', '00000000-0000-0000-0000-000000000001', 'Forgiveness Given', 'The grace of pardoning wrongs done.', 'story', 'trait', 'Introduce when mercy is offered.', '{"en":{"name":"Forgiveness Given","description":"The grace of pardoning wrongs done.","usage_examples":"Introduce when mercy is offered."},"ru":{"name":"Дарованное Прощение","description":"Благодать прощения совершенных проступков.","usage_examples":"Вводите, когда предлагается милосердие."},"ua":{"name":"Дароване Прощення","description":"Благодать прощення скоєних проступків.","usage_examples":"Вводьте, коли пропонується милосердя."}}', NULL),
('9d5b03ed-d9f6-5fff-b801-6862cf4326de', '00000000-0000-0000-0000-000000000001', 'Despair Overcome', 'The triumph of will over hopelessness.', 'story', 'trait', 'Use when darkness is defeated.', '{"en":{"name":"Despair Overcome","description":"The triumph of will over hopelessness.","usage_examples":"Use when darkness is defeated."},"ru":{"name":"Преодоленное Отчаяние","description":"Триумф воли над безнадежностью.","usage_examples":"Используйте, когда тьма побеждена."},"ua":{"name":"Подоланий Відчай","description":"Тріумф волі над безнадійністю.","usage_examples":"Використовуйте, коли темрява переможена."}}', NULL),
('0c732d63-78a4-5ce8-931f-65efe1daacd1', '00000000-0000-0000-0000-000000000001', 'Vengeance Taken', 'Retribution claimed for wrongs suffered.', 'story', 'trait', 'Play when justice or revenge is served.', '{"en":{"name":"Vengeance Taken","description":"Retribution claimed for wrongs suffered.","usage_examples":"Play when justice or revenge is served."},"ru":{"name":"Свершившаяся Месть","description":"Возмездие за перенесенные страдания.","usage_examples":"Играйте, когда свершается правосудие или месть."},"ua":{"name":"Здійснена Помста","description":"Відплата за перенесені страждання.","usage_examples":"Грайте, коли здійснюється правосуддя або помста."}}', NULL),
('0f0d980d-a0ae-5bf0-9714-1fb309db7513', '00000000-0000-0000-0000-000000000001', 'Wonder Rekindled', 'The return of amazement and appreciation for the extraordinary.', 'story', 'trait', 'Introduce when magic returns to life.', '{"en":{"name":"Wonder Rekindled","description":"The return of amazement and appreciation for the extraordinary.","usage_examples":"Introduce when magic returns to life."},"ru":{"name":"Возрожденное Чудо","description":"Возвращение изумления и признательности за необычное.","usage_examples":"Вводите, когда магия возвращается к жизни."},"ua":{"name":"Відроджене Диво","description":"Повернення подиву і вдячності за незвичайне.","usage_examples":"Вводьте, коли магія повертається до життя."}}', NULL)
INSERT INTO "public"."cards" (id, deck_id, name, description, type, category, usage_examples, translations, image_url) VALUES
('03b019e4-b6a1-5929-b870-d243fc2d25b5', '00000000-0000-0000-0000-000000000001', '…and the monster was vanquished.', 'The great evil is defeated, bringing victory to the heroes.', 'ending', NULL, 'Use for triumphant conclusions where good overcomes evil.', '{"en":{"name":"…and the monster was vanquished.","description":"The great evil is defeated, bringing victory to the heroes.","usage_examples":"Use for triumphant conclusions where good overcomes evil."},"ru":{"name":"…и монстр был побежден.","description":"Великое зло побеждено, принося победу героям.","usage_examples":"Используйте для триумфальных концовок, где добро побеждает зло."},"ua":{"name":"…і монстр був переможений.","description":"Велике зло переможене, приносячи перемогу героям.","usage_examples":"Використовуйте для тріумфальних кінцівок, де добро перемагає зло."}}', NULL),
('17a5b0b0-fe6d-57e6-858b-328114b9f332', '00000000-0000-0000-0000-000000000001', '…but the hero lost everything.', 'Victory came at a terrible price, leaving the champion broken.', 'ending', NULL, 'Play for pyrrhic victories or tragic sacrifices.', '{"en":{"name":"…but the hero lost everything.","description":"Victory came at a terrible price, leaving the champion broken.","usage_examples":"Play for pyrrhic victories or tragic sacrifices."},"ru":{"name":"…но герой потерял все.","description":"Победа досталась ужасной ценой, оставив чемпиона сломленным.","usage_examples":"Играйте для пирровых побед или трагических жертв."},"ua":{"name":"…але герой втратив усе.","description":"Перемога дісталася жахливою ціною, залишивши чемпіона зламаним.","usage_examples":"Грайте для піррових перемог або трагічних жертв."}}', NULL),
('88a5a3ad-834e-5bca-af13-aef3d4633c18', '00000000-0000-0000-0000-000000000001', '…and harmony was restored.', 'Balance and peace return to the world after conflict.', 'ending', NULL, 'Introduce when resolution brings equilibrium.', '{"en":{"name":"…and harmony was restored.","description":"Balance and peace return to the world after conflict.","usage_examples":"Introduce when resolution brings equilibrium."},"ru":{"name":"…и гармония была восстановлена.","description":"Баланс и мир возвращаются в мир после конфликта.","usage_examples":"Вводите, когда разрешение приносит равновесие."},"ua":{"name":"…і гармонія була відновлена.","description":"Баланс і мир повертаються у світ після конфлікту.","usage_examples":"Вводьте, коли вирішення приносить рівновагу."}}', NULL),
('40c53138-1cb1-5644-a9ae-6c7de305664e', '00000000-0000-0000-0000-000000000001', '…yet the curse endured.', 'Despite all efforts, the dark magic persists.', 'ending', NULL, 'Use for bittersweet or unresolved endings.', '{"en":{"name":"…yet the curse endured.","description":"Despite all efforts, the dark magic persists.","usage_examples":"Use for bittersweet or unresolved endings."},"ru":{"name":"…но проклятие осталось.","description":"Несмотря на все усилия, темная магия сохраняется.","usage_examples":"Используйте для горько-сладких или неразрешенных концовок."},"ua":{"name":"…але прокляття залишилося.","description":"Незважаючи на всі зусилля, темна магія зберігається.","usage_examples":"Використовуйте для гірко-солодких або невирішених кінцівок."}}', NULL),
('30ae0df4-85d0-5514-acae-5ed881da97ca', '00000000-0000-0000-0000-000000000001', '…and the journey changed them forever.', 'The adventure transformed the travelers in fundamental ways.', 'ending', NULL, 'Play when growth and change are the true victory.', '{"en":{"name":"…and the journey changed them forever.","description":"The adventure transformed the travelers in fundamental ways.","usage_examples":"Play when growth and change are the true victory."},"ru":{"name":"…и путешествие изменило их навсегда.","description":"Приключение фундаментально изменило путешественников.","usage_examples":"Играйте, когда рост и изменения являются истинной победой."},"ua":{"name":"…і подорож змінила їх назавжди.","description":"Пригода фундаментально змінила мандрівників.","usage_examples":"Грайте, коли ріст і зміни є справжньою перемогою."}}', NULL),
('fff4558f-eae4-55ec-83f7-0557f929cdd0', '00000000-0000-0000-0000-000000000001', '…but the truth was never spoken.', 'Secrets remained buried, shaping the future from shadow.', 'ending', NULL, 'Introduce when silence defines the outcome.', '{"en":{"name":"…but the truth was never spoken.","description":"Secrets remained buried, shaping the future from shadow.","usage_examples":"Introduce when silence defines the outcome."},"ru":{"name":"…но правда так и не была сказана.","description":"Секреты остались похороненными, формируя будущее из тени.","usage_examples":"Вводите, когда молчание определяет исход."},"ua":{"name":"…але правда так і не була сказана.","description":"Секрети залишилися похованими, формуючи майбутнє з тіні.","usage_examples":"Вводьте, коли мовчання визначає результат."}}', NULL),
('c2744374-a38f-5763-9c2c-1749f7415ec1', '00000000-0000-0000-0000-000000000001', '…and the kingdom was reborn.', 'From ruin, a new and better realm emerges.', 'ending', NULL, 'Use for renewal and reconstruction.', '{"en":{"name":"…and the kingdom was reborn.","description":"From ruin, a new and better realm emerges.","usage_examples":"Use for renewal and reconstruction."},"ru":{"name":"…и королевство возродилось.","description":"Из руин возникает новое и лучшее царство.","usage_examples":"Используйте для обновления и реконструкции."},"ua":{"name":"…і королівство відродилося.","description":"З руїн виникає нове і краще царство.","usage_examples":"Використовуйте для оновлення та реконструкції."}}', NULL),
('1f82f5d7-9f24-53cf-814e-38a1ee37c8a0', '00000000-0000-0000-0000-000000000001', '…and they vanished into legend.', 'The heroes became myth, their truth lost to time.', 'ending', NULL, 'Play when history becomes story.', '{"en":{"name":"…and they vanished into legend.","description":"The heroes became myth, their truth lost to time.","usage_examples":"Play when history becomes story."},"ru":{"name":"…и они исчезли в легендах.","description":"Герои стали мифом, их правда потеряна во времени.","usage_examples":"Играйте, когда история становится сказкой."},"ua":{"name":"…і вони зникли в легендах.","description":"Герої стали міфом, їхня правда втрачена в часі.","usage_examples":"Грайте, коли історія стає казкою."}}', NULL),
('884174b2-6428-5b3d-b738-f6588f96dd93', '00000000-0000-0000-0000-000000000001', '…but the price was too high.', 'Success was achieved, but the cost was unbearable.', 'ending', NULL, 'Introduce when victory feels like defeat.', '{"en":{"name":"…but the price was too high.","description":"Success was achieved, but the cost was unbearable.","usage_examples":"Introduce when victory feels like defeat."},"ru":{"name":"…но цена была слишком высока.","description":"Успех был достигнут, но стоимость была невыносимой.","usage_examples":"Вводите, когда победа ощущается как поражение."},"ua":{"name":"…але ціна була занадто висока.","description":"Успіх був досягнутий, але вартість була нестерпною. ","usage_examples":"Вводьте, коли перемога відчувається як поразка."}}', NULL),
('e6b9c30e-e8dc-545d-b246-9b25b2563ad2', '00000000-0000-0000-0000-000000000001', '…and the world forgot their name.', 'Great deeds were done, but memory faded.', 'ending', NULL, 'Use for forgotten heroes and lost glory.', '{"en":{"name":"…and the world forgot their name.","description":"Great deeds were done, but memory faded.","usage_examples":"Use for forgotten heroes and lost glory."},"ru":{"name":"…и мир забыл их имена.","description":"Великие дела были совершены, но память угасла.","usage_examples":"Используйте для забытых героев и потерянной славы."},"ua":{"name":"…і світ забув їхні імена.","description":"Великі справи були зроблені, але пам''ять згасла.","usage_examples":"Використовуйте для забутих героїв і втраченої слави."}}', NULL),
('b6e29905-bd9d-515a-a2c3-2899dc544f34', '00000000-0000-0000-0000-000000000001', '…and peace returned at last.', 'After long struggle, tranquility is finally achieved.', 'ending', NULL, 'Play for hard-won peaceful resolutions.', '{"en":{"name":"…and peace returned at last.","description":"After long struggle, tranquility is finally achieved.","usage_examples":"Play for hard-won peaceful resolutions."},"ru":{"name":"…и мир вернулся наконец.","description":"После долгой борьбы спокойствие наконец достигнуто.","usage_examples":"Играйте для мирных решений, доставшихся с трудом."},"ua":{"name":"…і мир повернувся нарешті.","description":"Після довгої боротьби спокій нарешті досягнуто.","usage_examples":"Грайте для мирних рішень, що дісталися важкою працею."}}', NULL),
('3d5909b8-9166-5806-b19a-961168a70b49', '00000000-0000-0000-0000-000000000001', '…but the shadows still whispered.', 'Darkness was pushed back but not eliminated.', 'ending', NULL, 'Introduce when evil lingers.', '{"en":{"name":"…but the shadows still whispered.","description":"Darkness was pushed back but not eliminated.","usage_examples":"Introduce when evil lingers."},"ru":{"name":"…но тени все еще шептали.","description":"Тьма была отброшена, но не уничтожена.","usage_examples":"Вводите, когда зло задерживается."},"ua":{"name":"…але тіні все ще шепотіли.","description":"Темрява була відкинута, але не знищена. ","usage_examples":"Вводьте, коли зло затримується."}}', NULL),
('e9864066-dbf3-562c-bcaa-658633b56448', '00000000-0000-0000-0000-000000000001', '…and the stars sang once more.', 'Joy and wonder return to a world that had forgotten them.', 'ending', NULL, 'Use for magical, uplifting conclusions.', '{"en":{"name":"…and the stars sang once more.","description":"Joy and wonder return to a world that had forgotten them.","usage_examples":"Use for magical, uplifting conclusions."},"ru":{"name":"…и звезды запели вновь.","description":"Радость и чудо возвращаются в мир, который забыл их.","usage_examples":"Используйте для магических, вдохновляющих концовок."},"ua":{"name":"…і зірки заспівали знову.","description":"Радість і диво повертаються у світ, який забув їх.","usage_examples":"Використовуйте для магічних, надихаючих кінцівок."}}', NULL),
('46b53170-f2b3-520c-afac-176df40740b0', '00000000-0000-0000-0000-000000000001', '…and the cycle began anew.', 'The pattern repeats, for better or worse.', 'ending', NULL, 'Play for cyclical or eternal recurrence.', '{"en":{"name":"…and the cycle began anew.","description":"The pattern repeats, for better or worse.","usage_examples":"Play for cyclical or eternal recurrence."},"ru":{"name":"…и цикл начался заново.","description":"Узор повторяется, к лучшему или к худшему.","usage_examples":"Играйте для циклических или вечных повторений."},"ua":{"name":"…і цикл почався заново.","description":"Візерунок повторюється, на краще чи на гірше.","usage_examples":"Грайте для циклічних або вічних повторень."}}', NULL),
('898e5dcc-c660-5c83-8f60-32b33d67f3c2', '00000000-0000-0000-0000-000000000001', '…but the hero never came home.', 'The champion was lost in their quest.', 'ending', NULL, 'Introduce when sacrifice means never returning.', '{"en":{"name":"…but the hero never came home.","description":"The champion was lost in their quest.","usage_examples":"Introduce when sacrifice means never returning."},"ru":{"name":"…но герой так и не вернулся домой.","description":"Чемпион был потерян в своем поиске.","usage_examples":"Вводите, когда жертва означает невозвращение."},"ua":{"name":"…але герой так і не повернувся додому.","description":"Чемпіон був втрачений у своєму пошуку.","usage_examples":"Вводьте, коли жертва означає неповернення."}}', NULL),
('f4612c13-a6c6-5842-bd5b-a7431627cdd9', '00000000-0000-0000-0000-000000000001', '…and the story was passed on.', 'The tale lives through those who tell it.', 'ending', NULL, 'Use when legacy is the true ending.', '{"en":{"name":"…and the story was passed on.","description":"The tale lives through those who tell it.","usage_examples":"Use when legacy is the true ending."},"ru":{"name":"…и история была передана дальше.","description":"Сказка живет через тех, кто ее рассказывает.","usage_examples":"Используйте, когда наследие является истинным концом."},"ua":{"name":"…і історія була передана далі.","description":"Казка живе через тих, хто її розповідає.","usage_examples":"Використовуйте, коли спадщина є справжнім кінцем."}}', NULL),
('155caca1-3f8b-596b-872c-e949d619a17e', '00000000-0000-0000-0000-000000000001', '…yet the wound never healed.', 'Some injuries persist despite all attempts to mend them.', 'ending', NULL, 'Play for lasting trauma or permanent change.', '{"en":{"name":"…yet the wound never healed.","description":"Some injuries persist despite all attempts to mend them.","usage_examples":"Play for lasting trauma or permanent change."},"ru":{"name":"…но рана так и не зажила.","description":"Некоторые травмы сохраняются, несмотря на все попытки их исцелить.","usage_examples":"Играйте для длительной травмы или постоянных изменений."},"ua":{"name":"…але рана так і не загоїлася.","description":"Деякі травми зберігаються, незважаючи на всі спроби їх зцілити.","usage_examples":"Грайте для тривалої травми або постійних змін."}}', NULL),
('55a85762-5224-547e-bb12-fcdb1e953654', '00000000-0000-0000-0000-000000000001', '…and the light returned.', 'Hope and brightness come back after darkness.', 'ending', NULL, 'Introduce for optimistic, healing conclusions.', '{"en":{"name":"…and the light returned.","description":"Hope and brightness come back after darkness.","usage_examples":"Introduce for optimistic, healing conclusions."},"ru":{"name":"…и свет вернулся.","description":"Надежда и яркость возвращаются после тьмы.","usage_examples":"Вводите для оптимистичных, исцеляющих концовок."},"ua":{"name":"…і світло повернулося.","description":"Надія і яскравість повертаються після темряви.","usage_examples":"Вводьте для оптимістичних, зцілюючих кінцівок."}}', NULL),
('74d4ebbe-39b4-5c2c-99a1-cfec1da06afe', '00000000-0000-0000-0000-000000000001', '…but the silence remained.', 'Quiet persists where there should be sound or life.', 'ending', NULL, 'Use for eerie or melancholic endings.', '{"en":{"name":"…but the silence remained.","description":"Quiet persists where there should be sound or life.","usage_examples":"Use for eerie or melancholic endings."},"ru":{"name":"…но тишина осталась.","description":"Спокойствие сохраняется там, где должен быть звук или жизнь.","usage_examples":"Используйте для жутких или меланхоличных концовок."},"ua":{"name":"…але тиша залишилася.","description":"Спокій зберігається там, де повинен бути звук або життя.","usage_examples":"Використовуйте для моторошних або меланхолійних кінцівок."}}', NULL),
('d4da3bef-b598-58f6-be66-a48563d52d08', '00000000-0000-0000-0000-000000000001', '…and they lived, changed, ever after.', 'Life continues, but those who lived it are forever altered.', 'ending', NULL, 'Play for realistic, transformative conclusions.', '{"en":{"name":"…and they lived, changed, ever after.","description":"Life continues, but those who lived it are forever altered.","usage_examples":"Play for realistic, transformative conclusions."},"ru":{"name":"…и они жили, изменившись, долго и счастливо.","description":"Жизнь продолжается, но те, кто ее прожил, навсегда изменились.","usage_examples":"Играйте для реалистичных, трансформирующих концовок."},"ua":{"name":"…і вони жили, змінившись, довго і щасливо.","description":"Життя триває, але ті, хто його прожив, назавжди змінилися.","usage_examples":"Грайте для реалістичних, трансформуючих кінцівок."}}', NULL)
